    from . import core_payment_provider_edge as provider_edge
    from . import core_payment_service as svc
except ImportError:  # pragma: no cover - supports direct app-folder deployment.
    import core_access_gateway as access_gateway
    import core_identity_session as identity_session
    import core_payment_provider_edge as provider_edge
    import core_payment_service as svc


router = APIRouter()
STAFF_FINANCE_AUTH_ROLES = {
    "operator",
    "ops",
    "ops_manager",
    "super_admin",
    "owner",
    "landlord",
    "freelancer",
    "accountant",
    "finance",
    "finance_ops",
    "finance_manager",
}
FOUNDER_PAYMENT_CONTROL_ROLES = {
    "operator",
    "ops",
    "ops_manager",
    "super_admin",
    "owner",
    "finance",
    "finance_ops",
    "finance_manager",
}
SCOPED_FINANCE_AUTH_ROLES = STAFF_FINANCE_AUTH_ROLES | {
    "partner",
    "agent",
    "school",
    "family",
    "parent",
    "student",
    "guardian",
    "tenant",
    "member",
}


def _request_meta(request: Request) -> Dict[str, str]:
    return {
        "ip": request.client.host if request.client else "",
        "user_agent": str(request.headers.get("user-agent") or "")[:500],
        "referer": str(request.headers.get("referer") or "")[:500],
    }


def _raise_if_error(response: Dict[str, Any]) -> Dict[str, Any]:
    if response.get("ok") is not False:
        return response

    detail = str(response.get("detail") or "core_payment_error")
    status_code = int(response.get("status_code") or 400)
    if detail == "identity_session_required":
        status_code = 401
    raise HTTPException(
        status_code=status_code,
        detail=detail,
    )


def _payment_read_scope(request: Request, path: str, allowed_roles: set[str]) -> Dict[str, Any]:
    resolved = identity_session.resolve_access_context(
        headers=request.headers,
        method=request.method,
        path=path,
        request_meta=_request_meta(request),
        require_identity=True,
    )
    if resolved.get("ok") is False:
        return resolved
    access = resolved.get("access") if isinstance(resolved.get("access"), dict) else {}
    actor = access.get("actor") if isinstance(access.get("actor"), dict) else {}
    actor_id = str(actor.get("actor_id") or "")
    role = str(actor.get("role") or "")
    if role not in allowed_roles or not actor_id:
        return {"ok": False, "detail": "payment_reader_identity_required", "status_code": 403}
    return {
        "ok": True,
        "workspace_id": str(access.get("workspace_id") or svc.DEFAULT_WORKSPACE_ID),
        "actor_id": actor_id,
        "role": role,
    }


def _payment_case_scope(request: Request, path: str, case_id: str) -> Dict[str, Any]:
    scope = _payment_read_scope(request, path, SCOPED_FINANCE_AUTH_ROLES)
    if scope.get("ok") is False:
        return scope
    if _viewer_role_for_actor(str(scope.get("role") or "")) not in svc.FULL_FINANCE_VIEWER_ROLES:
        case_access = svc.case_svc.authorize_pass_case_access(
            case_id,
            str(scope.get("workspace_id") or svc.DEFAULT_WORKSPACE_ID),
            str(scope.get("actor_id") or ""),
            str(scope.get("role") or ""),
        )
        if case_access.get("ok") is False:
            return case_access
    return scope


def _viewer_role_for_actor(role: str) -> str:
    normalized = str(role or "").strip().lower()
    if normalized in {"ops", "ops_manager", "super_admin"}:
        return "operator"
    if normalized in {"finance_ops", "finance_manager"}:
        return "finance"
    if normalized in {"guardian", "tenant", "member"}:
        return "family"
    if normalized in set(svc.ALLOWED_FINANCE_VIEWER_ROLES):
        return normalized
    return "operator"


def _provider_secret_ref_id(request: Request) -> str:
    header_value = str(request.headers.get("x-liveuin-provider-secret-ref-id") or "").strip()
    if header_value:
        return header_value
    query_value = str(request.query_params.get("provider_secret_ref_id") or "").strip()
    if query_value:
        return query_value
    return ""


