def _hash_payload(value: Dict[str, Any]) -> str:
    import hashlib
    import json

    serialized = json.dumps(value, ensure_ascii=True, sort_keys=True, separators=(",", ":"))
    return hashlib.sha256(serialized.encode("utf-8")).hexdigest()


