def _g36_safe_evidence_refs(items: Any) -> List[Dict[str, Any]]:
    refs: List[Dict[str, Any]] = []
    for item in _as_list(items):
        source = _as_dict(item)
        ref_id = _clean_id(source.get("ref_id") or source.get("evidence_id") or source.get("id"), 120)
        if not ref_id:
            continue
        refs.append(
            {
                "ref_id": ref_id,
                "type": _clean_slug(source.get("type"), "payment_evidence", max_length=80),
                "state": _clean_slug(source.get("state"), "submitted", max_length=80),
                "source_family": _clean_slug(source.get("source_family") or source.get("source"), "liveuin_trustpay", max_length=120),
                "summary": _clean_string(source.get("summary"), 160),
            }
        )
    return refs[:24]


def _g36_fee_items(items: Any, currency: str) -> List[Dict[str, Any]]:
    normalized: List[Dict[str, Any]] = []
    for item in _as_list(items):
        source = _as_dict(item)
        amount = _bounded_int(source.get("amount") or source.get("amount_minor"), 0)
        if amount <= 0:
            continue
        normalized.append(
            {
                "label": _clean_string(source.get("label") or source.get("name") or "fee", 120),
                "amount": amount,
                "currency": _clean_string(source.get("currency") or currency, 12).upper() or currency,
                "kind": _clean_slug(source.get("kind") or source.get("type"), "fee", max_length=80),
                "beneficiary_entity_id": _clean_id(source.get("beneficiary_entity_id") or source.get("entity_id"), 96),
            }
        )
    return normalized[:24]


