def _g36_build_money_map(
    *,
    workspace_id: str,
    case_id: str,
    booking_id: str,
    purpose_type: str,
    purpose_id: str,
    payer_id: str,
    amount: int,
    currency: str,
    due_at: int,
    data: Dict[str, Any],
    raw_metadata: Dict[str, Any],
    booking_record: Dict[str, Any],
    booking_offer_binding: Dict[str, Any],
    pricing: Dict[str, Any],
    finance_enforcement: Dict[str, Any],
) -> Dict[str, Any]:
    precommit = _g36_precommit_projection(case_id, workspace_id)
    if precommit.get("ok") is False:
        return precommit
    precommit_projection = _as_dict(precommit.get("precommit_responsibility"))
    payee_entity_id = _clean_id(
        data.get("payee_entity_id")
        or raw_metadata.get("payee_entity_id")
        or precommit_projection.get("payee_entity_id"),
        96,
    )
    if not payee_entity_id:
        return error("payment_obligation_payee_role_required", 409)
    agreement_binding = _g36_current_agreement_binding(booking_id, workspace_id)
    agreement_version_id = _clean_string(agreement_binding.get("agreement_version_id"), 160)
    if not agreement_version_id:
        return error("payment_obligation_version_required", 409)
    catalogue_version_id = _clean_string(
        raw_metadata.get("catalogue_version_id")
        or data.get("catalogue_version_id")
        or (
            f"{_clean_id(pricing.get('price_book_id'), 96)}:{_clean_id(pricing.get('price_book_version'), 48)}"
            if pricing.get("price_book_id") and pricing.get("price_book_version")
            else ""
        ),
        160,
    )
    if not catalogue_version_id:
        catalogue_version_id = agreement_version_id
    evidence_refs = _g36_safe_evidence_refs(data.get("evidence_refs") or raw_metadata.get("evidence_refs"))
    if not evidence_refs:
        evidence_refs = [
            {
                "ref_id": agreement_version_id,
                "type": "agreement_version",
                "state": "current",
                "source_family": "liveuin_agreement_runtime",
                "summary": "Current agreement version anchors the canonical obligation packet.",
            }
        ]
    tax_fee_amount = _bounded_int(data.get("tax_fee_amount") or raw_metadata.get("tax_fee_amount"), 0)
    commission_amount = _bounded_int(
        data.get("commission_amount")
        or raw_metadata.get("commission_amount")
        or raw_metadata.get("partner_fee_amount"),
        0,
    )
    if tax_fee_amount + commission_amount > amount:
        return error("payment_obligation_breakdown_exceeds_amount", 409)
    beneficiary_entity_id = _clean_id(
        data.get("beneficiary_entity_id")
        or raw_metadata.get("beneficiary_entity_id")
        or raw_metadata.get("housing_payee_entity")
        or payee_entity_id,
        96,
    )
    commission_beneficiary_entity = _clean_id(
        data.get("commission_beneficiary_entity_id")
        or raw_metadata.get("commission_beneficiary_entity_id")
        or raw_metadata.get("source_partner_id"),
        96,
    )
    tax_fee_beneficiary_entity = _clean_id(
        data.get("tax_fee_beneficiary_entity_id")
        or raw_metadata.get("tax_fee_beneficiary_entity_id"),
        96,
    )
    due_condition = _clean_string(data.get("due_condition") or raw_metadata.get("due_condition") or "commitment_required_before_payment", 160)
    refundability_state = _clean_slug(
        data.get("refundability_state") or raw_metadata.get("refundability_state") or raw_metadata.get("refundability") or "review_required",
        "review_required",
        max_length=80,
    )
    net_beneficiary_amount = max(0, amount - tax_fee_amount - commission_amount)
    ledger_projection: List[Dict[str, Any]] = [
        {"entry_type": "debit", "party": "payer", "entity_id": _clean_id(payer_id, 96), "amount": amount, "currency": currency},
        {"entry_type": "credit", "party": "beneficiary", "entity_id": beneficiary_entity_id, "amount": net_beneficiary_amount, "currency": currency},
    ]
    if tax_fee_amount > 0:
        ledger_projection.append(
            {
                "entry_type": "credit",
                "party": "tax_fee",
                "entity_id": tax_fee_beneficiary_entity,
                "amount": tax_fee_amount,
                "currency": currency,
            }
        )
    if commission_amount > 0:
        ledger_projection.append(
            {
                "entry_type": "credit",
                "party": "commission",
                "entity_id": commission_beneficiary_entity,
                "amount": commission_amount,
                "currency": currency,
            }
        )
    debit_total = sum(int(item.get("amount") or 0) for item in ledger_projection if item.get("entry_type") == "debit")
    credit_total = sum(int(item.get("amount") or 0) for item in ledger_projection if item.get("entry_type") == "credit")
    payload = {
        "object_version": G36_MONEY_MAP_OBJECT_VERSION,
        "case_id": case_id,
        "booking_id": booking_id,
        "purpose_type": purpose_type,
        "purpose_id": purpose_id,
        "payer_id": _clean_id(payer_id, 96),
        "catalogue_version_id": catalogue_version_id,
        "price_book_id": _clean_id(pricing.get("price_book_id"), 96),
        "price_book_version": _clean_id(pricing.get("price_book_version"), 48),
        "price_key": _clean_slug(pricing.get("price_key"), "", max_length=80),
        "agreement_instance_id": _clean_id(agreement_binding.get("agreement_instance_id"), 96),
        "agreement_version_id": agreement_version_id,
        "offer_version_binding": booking_offer_binding,
        "amount": amount,
        "currency": currency,
        "tax_fee": {
            "amount": tax_fee_amount,
            "currency": currency,
            "items": _g36_fee_items(data.get("tax_fee_items") or raw_metadata.get("tax_fee_items"), currency),
            "beneficiary_entity_id": tax_fee_beneficiary_entity,
        },
        "deposit": {
            "amount": _bounded_int(
                data.get("deposit_amount")
                or raw_metadata.get("deposit_amount")
                or booking_record.get("deposit_amount")
                or (amount if purpose_type == "deposit" else 0),
                0,
            ),
            "currency": currency,
            "required": purpose_type == "deposit" or _bounded_int(booking_record.get("deposit_amount"), 0) > 0,
        },
        "commission": {
            "amount": commission_amount,
            "currency": currency,
            "state": _clean_slug(
                data.get("commission_state")
                or raw_metadata.get("commission_state")
                or raw_metadata.get("partner_fee_state")
                or ("pending" if commission_amount > 0 else "not_required"),
                "not_required",
                max_length=80,
            ),
            "beneficiary_entity_id": commission_beneficiary_entity,
        },
        "payee": {
            "entity_id": payee_entity_id,
            "label": _clean_string(
                data.get("payee_label")
                or raw_metadata.get("payee_label")
                or precommit_projection.get("payee_label"),
                120,
            ),
            "role_slot": "payee",
            "precommit_version": int(precommit_projection.get("version") or 0),
        },
        "beneficiary": {
            "entity_id": beneficiary_entity_id,
            "label": _clean_string(data.get("beneficiary_label") or raw_metadata.get("beneficiary_label"), 120),
        },
        "due": {
            "due_at": due_at,
            "due_at_iso": _iso_from_epoch(due_at),
            "condition": due_condition,
        },
        "refundability": {
            "state": refundability_state,
            "policy_ref": _clean_string(data.get("refundability_policy_ref") or raw_metadata.get("refundability_policy_ref"), 160),
            "conditions": _clean_string(data.get("refundability_conditions") or raw_metadata.get("refundability_conditions"), 240),
        },
        "evidence_refs": evidence_refs,
        "runtime_reference": {
            "runtime_activation_record_id": _clean_id(finance_enforcement.get("runtime_activation_record_id"), 96),
            "approved_finance_snapshot_id": _clean_id(finance_enforcement.get("approved_finance_snapshot_id"), 96),
            "payer_liability_policy_id": _clean_id(finance_enforcement.get("payer_liability_policy_id"), 96),
            "billing_cycle_policy_id": _clean_id(finance_enforcement.get("billing_cycle_policy_id"), 96),
            "payment_mandate_policy_id": _clean_id(finance_enforcement.get("payment_mandate_policy_id"), 96),
            "finance_classification_snapshot_id": _clean_id(finance_enforcement.get("finance_classification_snapshot_id"), 96),
            "finance_classification_version_id": _clean_string(finance_enforcement.get("finance_classification_version_id"), 160),
            "finance_classification_hash": _clean_string(finance_enforcement.get("finance_classification_hash"), 160),
        },
        "ledger_projection": ledger_projection,
        "ledger_projection_balanced": debit_total == credit_total,
        "source_guard": _source_guard(),
    }
    payload["money_map_hash"] = _hash_payload(payload)
    return {"ok": True, "payload": payload}


def _g36_store_money_map(
    booking_id: str,
    purpose_type: str,
    workspace_id: str,
    payload: Dict[str, Any],
    request_meta: Dict[str, str] | None = None,
) -> Dict[str, Any]:
    existing = _g36_money_map_current(booking_id, purpose_type, workspace_id)
    if existing and _clean_string(_as_dict(existing.get("payload")).get("money_map_hash"), 160) == _clean_string(payload.get("money_map_hash"), 160):
        return {"ok": True, "money_map": _g36_projection(existing), "replay": True}
    version = int(existing.get("version") or 0) + 1 if existing else 1
    document = runtime_store.put_document(
        {
            "object_type": G36_MONEY_MAP_DOCUMENT_TYPE,
            "object_id": _g36_object_id(booking_id, purpose_type),
            "version": version,
            "workspace_id": workspace_id,
            "scope_type": "booking",
            "scope_id": booking_id,
            "country_code": _clean_string(_as_dict(payload.get("runtime_reference")).get("country_code") or "SG", 24).upper(),
            "state": "payment_ready" if _bool(payload.get("ledger_projection_balanced"), False) else "review_required",
            "effective_from": _now(),
            "payload": payload,
            "metadata": {
                "request_meta": _as_dict(request_meta),
                "updated_from": "core_payment_service",
            },
        }
    )
    return {"ok": True, "money_map": _g36_projection(document), "replay": False}


def _g36_bill_current_guard(bill: Dict[str, Any], workspace_id: str) -> Dict[str, Any]:
    booking_id = _clean_id(bill.get("booking_id"), 96)
    if not booking_id:
        return error("payment_obligation_version_required", 409, bill_id=_clean_id(bill.get("bill_id"), 96))
    snapshot = _bill_money_map(bill)
    snapshot_version_id = _money_map_version_id(snapshot)
    snapshot_hash = _money_map_hash(snapshot)
    if not snapshot_version_id or not snapshot_hash:
        return error("payment_obligation_version_required", 409, bill_id=_clean_id(bill.get("bill_id"), 96))
    current_document = _g36_money_map_current(booking_id, _clean_slug(bill.get("purpose_type"), "deposit", max_length=80), workspace_id)
    if not current_document:
        return error("payment_obligation_version_required", 409, bill_id=_clean_id(bill.get("bill_id"), 96))
    current_projection = _g36_projection(current_document)
    if (
        current_projection.get("money_map_version_id") != snapshot_version_id
        or current_projection.get("money_map_hash") != snapshot_hash
    ):
        return error(
            "payment_obligation_changed_requires_renewed_decision",
            409,
            bill_id=_clean_id(bill.get("bill_id"), 96),
            current_money_map_version_id=current_projection.get("money_map_version_id", ""),
        )
    current_agreement = _g36_current_agreement_binding(booking_id, workspace_id)
    if current_agreement and current_projection.get("agreement_version_id") != current_agreement.get("agreement_version_id"):
        return error(
            "payment_obligation_changed_requires_renewed_decision",
            409,
            bill_id=_clean_id(bill.get("bill_id"), 96),
            current_agreement_version_id=current_agreement.get("agreement_version_id", ""),
        )
    if int(current_projection.get("amount") or 0) != int(bill.get("amount") or 0):
        return error("payment_obligation_mismatch", 409, bill_id=_clean_id(bill.get("bill_id"), 96))
    if str(current_projection.get("currency") or "SGD") != str(bill.get("currency") or "SGD"):
        return error("payment_obligation_mismatch", 409, bill_id=_clean_id(bill.get("bill_id"), 96))
    return {"ok": True, "money_map": current_projection}


def _redact(value: Any) -> Any:
    if isinstance(value, dict):
        clean: Dict[str, Any] = {}
        for key, item in value.items():
            key_text = str(key)
            normalized = key_text.lower()
            if normalized in SECRET_KEYS or any(fragment in normalized for fragment in ("secret", "token", "signature", "card_number", "cvv", "bank_account")):
                continue
            clean[key_text] = _redact(item)
        return clean
    if isinstance(value, list):
        return [_redact(item) for item in value[:50]]
    if isinstance(value, str) and value.startswith(("http://", "https://")):
        return "[redacted_url]"
    return value


def _contact_hint(payload: Dict[str, Any]) -> str:
    for key in ("email", "phone", "wechat_id", "whatsapp"):
        value = _clean_string(payload.get(key), 120)
        if value:
            if "@" in value:
                name, _, domain = value.partition("@")
                return (name[:2] + "***@" + domain[:24])[:80]
            return ("***" + value[-4:])[:80]
    return ""


def _premium_finance_metadata(
    payload: Dict[str, Any] | None = None,
    existing: Dict[str, Any] | None = None,
    *,
    bill_currency: str = "SGD",
    payment_received_at: str = "",
) -> Dict[str, Any]:
    payload = _as_dict(payload)
    existing = _as_dict(existing)
    metadata = _as_dict(payload.get("metadata"))

    def _pick(*keys: str) -> Any:
        for key in keys:
            if payload.get(key) not in (None, ""):
                return payload.get(key)
            if metadata.get(key) not in (None, ""):
                return metadata.get(key)
            if existing.get(key) not in (None, ""):
                return existing.get(key)
        return ""

    collection_mode_raw = _pick("partner_collection_mode")
    tenant_pays_partner = _bool(_pick("tenant_pays_partner"), _bool(existing.get("tenant_pays_partner")))
    default_collection_mode = "partner_collected" if tenant_pays_partner else "direct_pay"
    collection_mode = _clean_slug(
        collection_mode_raw or existing.get("partner_collection_mode"),
        default_collection_mode,
        ALLOWED_PARTNER_COLLECTION_MODES,
    )
    provider = _clean_slug(payload.get("provider"), "", max_length=80) if payload.get("provider") else ""
    method = _clean_slug(payload.get("method"), "", max_length=80) if payload.get("method") else ""
    derived_channel = ""
    if provider and method:
        derived_channel = provider + "_" + method
    elif provider:
        derived_channel = provider
    elif method:
        derived_channel = method
    tenant_payment_channel = _clean_string(_pick("tenant_payment_channel") or derived_channel, 80)
    tenant_payment_received_at = _clean_string(_pick("tenant_payment_received_at") or payment_received_at, 40)
    partner_remitted_at = _clean_string(_pick("partner_remitted_at"), 40)
    partner_remittance_due_at = _clean_string(_pick("partner_remittance_due_at"), 40)
    partner_remittance_evidence_ref = _clean_string(_pick("partner_remittance_evidence_ref"), 160)
    partner_fee_amount = _bounded_int(_pick("partner_fee_amount"), _bounded_int(existing.get("partner_fee_amount"), 0))
    partner_fee_currency = _clean_string(
        _pick("partner_fee_currency") or bill_currency or existing.get("partner_fee_currency") or "SGD",
        12,
    ).upper()
    partner_fee_state = _clean_slug(
        _pick("partner_fee_state"),
        "not_required" if partner_fee_amount <= 0 else "pending",
        max_length=80,
    )
    premium_lane = _bool(_pick("premium_lane"), _bool(existing.get("premium_lane")))
    source_partner_id = _clean_id(_pick("source_partner_id") or _pick("partner_id"), 96)
    partner_case_ref = _clean_id(_pick("partner_case_ref") or _pick("source_partner_case_ref"), 96)
    preferred_payment_mode = _clean_slug(_pick("preferred_payment_mode"), "", max_length=80)
    refund_owner_entity = _clean_string(_pick("refund_owner_entity"), 120)
    remittance_owner_entity = _clean_string(_pick("remittance_owner_entity"), 120)
    collection_entity = _clean_string(_pick("collection_entity"), 120)
    contracting_entity = _clean_string(_pick("contracting_entity"), 120)
    housing_payee_entity = _clean_string(_pick("housing_payee_entity"), 120)
    receipt_issuer_entity = _clean_string(_pick("receipt_issuer_entity"), 120)
    has_signal = any(
        [
            premium_lane,
            source_partner_id,
            partner_case_ref,
            preferred_payment_mode,
            collection_mode_raw,
            tenant_pays_partner,
            refund_owner_entity,
            remittance_owner_entity,
            collection_entity,
            contracting_entity,
            housing_payee_entity,
            receipt_issuer_entity,
            partner_remittance_due_at,
            partner_remitted_at,
            partner_remittance_evidence_ref,
            partner_fee_amount > 0,
            _pick("partner_fee_state"),
        ]
    )
    if not has_signal:
        return {}
    return {
        "premium_lane": premium_lane,
        "premium_lane_type": _clean_slug(_pick("premium_lane_type"), "liuzhu_style", max_length=80),
        "source_partner_id": source_partner_id,
        "partner_case_ref": partner_case_ref,
        "preferred_payment_mode": preferred_payment_mode,
        "tenant_pays_partner": tenant_pays_partner,
        "partner_collection_mode": collection_mode,
        "partner_remittance_mode": _clean_slug(_pick("partner_remittance_mode"), "manual_with_evidence", max_length=80),
        "collection_entity": collection_entity,
        "contracting_entity": contracting_entity,
        "housing_payee_entity": housing_payee_entity,
        "receipt_issuer_entity": receipt_issuer_entity,
        "refund_owner_entity": refund_owner_entity,
        "remittance_owner_entity": remittance_owner_entity,
        "tenant_payment_channel": tenant_payment_channel,
        "tenant_payment_received_at": tenant_payment_received_at,
        "partner_remittance_due_at": partner_remittance_due_at,
        "partner_remitted_at": partner_remitted_at,
        "partner_remittance_evidence_ref": partner_remittance_evidence_ref,
        "partner_remittance_status": (
            "not_required"
            if collection_mode != "partner_collected"
            else ("remitted" if partner_remitted_at else "pending")
        ),
        "partner_fee_amount": partner_fee_amount,
        "partner_fee_currency": partner_fee_currency,
        "partner_fee_state": partner_fee_state,
        "canonical_owner": "LiveUIN TrustPay/LiveLedger",
        "payment_provider_truth_used": False,
    }


