def _bill_context(bill: Dict[str, Any]) -> Dict[str, Any]:
    metadata = _as_dict(bill.get("metadata"))
    receipt = _as_dict(bill.get("receipt"))
    property_id = _clean_id(
        metadata.get("property_id")
        or metadata.get("master_property_id")
        or metadata.get("parent_property_id")
        or receipt.get("property_id"),
        96,
    )
    room_id = _clean_id(metadata.get("room_id") or metadata.get("unit_id") or receipt.get("room_id"), 96)
    issuer_id = _clean_id(
        metadata.get("issuer_id")
        or metadata.get("operator_id")
        or metadata.get("owner_id")
        or metadata.get("payee_id"),
        96,
    )
    return {
        "property_id": property_id,
        "room_id": room_id,
        "issuer_id": issuer_id,
        "country_code": _clean_string(metadata.get("country_code") or metadata.get("country"), 24).upper(),
        "document_refs": [_clean_id(item, 96) for item in _as_list(metadata.get("document_ids")) if _clean_id(item, 96)],
    }


def _bill_matches_property(bill: Dict[str, Any], property_id: str) -> bool:
    if not property_id:
        return False
    context = _bill_context(bill)
    candidates = {
        property_id,
        context.get("property_id", ""),
        context.get("room_id", ""),
        _clean_id(bill.get("purpose_id"), 96),
    }
    candidates.discard("")
    return property_id in candidates


