def _documents_for_property(
    property_id: str,
    bills: List[Dict[str, Any]],
    refunds: List[Dict[str, Any]],
    visibility: Dict[str, Any],
) -> List[Dict[str, Any]]:
    documents: List[Dict[str, Any]] = []
    for bill in bills:
        bill_id = bill.get("bill_id", "")
        case_id = bill.get("case_id", "")
        status = str(bill.get("status") or "unpaid")
        documents.append(
            _payment_document(
                document_id="invoice_" + bill_id,
                document_type="invoice",
                label=bill.get("description") or "Property invoice",
                status=status,
                property_id=property_id,
                case_id=case_id,
                bill_id=bill_id,
                downloadable=visibility.get("download_allowed") is True,
            )
        )
        if status in {"paid", "reconciled", "settled", "refunded", "partially_refunded"}:
            documents.append(
                _payment_document(
                    document_id="receipt_" + bill_id,
                    document_type="receipt",
                    label=(bill.get("description") or "Property invoice") + " receipt",
                    status="available" if _as_dict(bill.get("receipt")) else "pending",
                    property_id=property_id,
                    case_id=case_id,
                    bill_id=bill_id,
                    downloadable=visibility.get("download_allowed") is True,
                )
            )
    for refund in refunds:
        refund_id = refund.get("refund_id", "")
        bill_id = refund.get("bill_id", "")
        documents.append(
            _payment_document(
                document_id="credit_note_" + refund_id,
                document_type="credit_note",
                label=refund.get("reason") or "Credit note / refund memo",
                status=refund.get("status", "requested"),
                property_id=property_id,
                case_id=refund.get("case_id", ""),
                bill_id=bill_id,
                refund_id=refund_id,
                downloadable=visibility.get("download_allowed") is True,
            )
        )
    return documents


def _property_finance_summary(
    *,
    property_id: str,
    bills: List[Dict[str, Any]],
    exceptions: List[Dict[str, Any]],
    refunds: List[Dict[str, Any]],
    documents: List[Dict[str, Any]],
) -> Dict[str, Any]:
    safe_bills = [_bill_safe(item) for item in bills]
    summary = _payment_summary([_canonical_payment_from_bill(item) for item in bills], [_exception_safe(item) for item in exceptions], [_refund_safe(item) for item in refunds])
    outstanding_amount = int(summary.get("amount_due") or 0)
    paid_count = int(summary.get("paid_count") or 0)
    receipt_state = "receipt_ready" if paid_count > 0 and any(doc.get("document_type") == "receipt" for doc in documents) else ("not_started" if paid_count <= 0 else "pending")
    payout_state = "payout_review" if int(summary.get("amount_paid") or 0) > 0 else "not_started"
    finance_status = "review" if summary.get("open_exception_count") else ("payment_due" if outstanding_amount > 0 else ("paid" if paid_count > 0 else "clear"))
    refund_escalated = any(
        str(item.get("status") or "") in REFUND_ESCALATED_STATUSES
        or bool(_as_dict(item.get("settlement")).get("provider_delay_visible"))
        for item in refunds
    )
    if refunds:
        finance_status = "refund_escalated" if refund_escalated else ("refund_review" if any(item.get("status") != "completed" for item in refunds) else "refunded")
    if summary.get("open_exception_count"):
        next_action = "Resolve payment exception(s)"
    elif outstanding_amount > 0:
        next_action = "Collect outstanding balance"
    elif refund_escalated:
        next_action = "Recover or reconcile escalated refund"
    elif refunds and any(item.get("status") != "completed" for item in refunds):
        next_action = "Complete refund workflow"
    elif paid_count > 0:
        next_action = "Review payout and export readiness"
    else:
        next_action = "Issue first invoice"
    issuer_id = ""
    for bill in bills:
        issuer_id = _bill_context(bill).get("issuer_id", "")
        if issuer_id:
            break
    country_code = ""
    for bill in bills:
        country_code = _bill_context(bill).get("country_code", "")
        if country_code:
            break
    return {
        "property_id": property_id,
        "issuer_id": issuer_id,
        "finance_status": finance_status,
        "outstanding_amount": outstanding_amount,
        "receipt_state": receipt_state,
        "payout_state": payout_state,
        "remediation_state": "not_loaded",
        "exception_count": int(summary.get("open_exception_count") or 0),
        "next_action": next_action,
        "linked_case_count": len({item.get("case_id", "") for item in safe_bills if item.get("case_id")}),
        "document_count": len(documents),
        "country_code": country_code,
        "summary": summary,
    }


