    request_meta: Dict[str, str] | None = None,
) -> str:
    event_id = "pay_evt_" + uuid.uuid4().hex[:16]
    safe_payload = {
        **_as_dict(_redact(payload or {})),
        "source": "liveuin_trustpay",
