        "liveuin_ops_refund_review",
        max_length=80,
    )


def _refund_status_group(status: str, *, delayed: bool = False) -> str:
    if delayed:
        return "refund_delay"
    if status == "completed":
        return "refund_completed"
    if status in REFUND_ESCALATED_STATUSES:
        return "refund_escalated"
    if status == "cancelled":
        return "refund_cancelled"
    return "refund_review"


def _refund_settlement_state(status: str, *, partial: bool = False, delayed: bool = False) -> str:
    if status == "requested":
        return "pending_review"
    if status == "reviewing":
        return "under_review"
    if status == "approved":
        return "approved_pending_execution"
    if status == "initiated":
        return "provider_delay_visible" if delayed else "awaiting_provider_settlement"
    if status == "completed":
        return "partially_settled" if partial else "settled"
    if status == "failed":
        return "provider_failed"
    if status == "disputed":
        return "disputed"
    if status == "cancelled":
        return "cancelled"
    return status


def _refund_delay_visible(
    data: Dict[str, Any],
    *,
    status: str,
    previous_summary: Dict[str, Any],
) -> bool:
    if status != "initiated":
        return False
    if _bool(data.get("provider_delay_visible")):
        return True
    expected = _clean_string(
        data.get("expected_settlement_at")
        or _as_dict(data.get("settlement")).get("expected_settlement_at")
        or _as_dict(previous_summary.get("settlement")).get("expected_settlement_at"),
        40,
    )
    expected_epoch = _epoch_from_any(expected)
    return expected_epoch > 0 and expected_epoch < _now()


def _refund_calculation(
    *,
    bill: Dict[str, Any],
    refund: Dict[str, Any] | None,
    amount: int,
    currency: str,
    status: str,
    reason: str,
    available_before: int,
    completed_before: int,
    completed_after: int,
) -> Dict[str, Any]:
    refund = refund or {}
    bill_amount = int(bill.get("amount") or 0)
    return {
        "bill_total_amount": bill_amount,
        "requested_amount": amount,
        "approved_amount": amount if status in {"approved", "initiated", "completed", "failed", "disputed"} else 0,
        "completed_amount": amount if status == "completed" else 0,
        "currency": currency,
        "available_amount_before_request": max(0, available_before),
        "available_amount_after_update": max(0, bill_amount - completed_after),
        "completed_refund_amount_before": max(0, completed_before),
        "completed_refund_amount_after": max(0, completed_after),
        "partial_refund": status == "completed" and completed_after < bill_amount,
        "full_refund": status == "completed" and completed_after >= bill_amount,
        "calculation_basis": "canonical_trustpay_bill_and_refund_records",
        "reason_code": reason,
        "source": _refund_source({}, refund),
    }


def _refund_approval(
    *,
    data: Dict[str, Any],
    request_meta: Dict[str, str] | None,
    status: str,
    previous_summary: Dict[str, Any],
) -> Dict[str, Any]:
    previous = _as_dict(previous_summary.get("approval"))
    actor_id = _clean_id((request_meta or {}).get("access_actor_id"), 96)
    actor_role = _clean_slug((request_meta or {}).get("access_actor_role"), "", max_length=80)
    approved_at = _clean_string(
        data.get("approved_at")
        or previous.get("approved_at")
        or (_now_iso() if status in {"approved", "initiated", "completed", "failed", "disputed"} else ""),
        40,
    )
    review_state = "requested"
    if status == "reviewing":
        review_state = "under_review"
    elif status in {"approved", "initiated", "completed"}:
        review_state = "approved"
    elif status in {"failed", "disputed"}:
        review_state = "approved_execution_exception"
    elif status == "cancelled":
        review_state = "cancelled"
    return {
        "state": review_state,
        "approved_at": approved_at if review_state != "requested" else "",
        "approved_by_actor_id": actor_id if review_state != "requested" else _clean_id(previous.get("approved_by_actor_id"), 96),
        "approved_by_role": actor_role if review_state != "requested" else _clean_slug(previous.get("approved_by_role"), "", max_length=80),
        "approval_ref": _clean_string(data.get("approval_ref") or previous.get("approval_ref"), 160),
        "approval_source": _refund_source(data),
        "approval_note": _clean_string(data.get("approval_note") or data.get("note") or previous.get("approval_note"), 240),
        "manual_approval_required": status not in {"cancelled"},
    }


def _refund_communication(
    *,
    data: Dict[str, Any],
    status: str,
    delayed: bool,
    previous_summary: Dict[str, Any],
) -> Dict[str, Any]:
    previous = _as_dict(previous_summary.get("communication"))
    state = "pending_review"
    if status in {"approved", "initiated"}:
        state = "queued"
    if status == "completed":
        state = "sent"
    elif status in REFUND_ESCALATED_STATUSES or delayed:
        state = "escalated"
    elif status == "cancelled":
        state = "cancelled"
    return {
        "state": state,
        "channel": _clean_slug(data.get("communication_channel") or previous.get("channel"), "case_timeline", max_length=80),
        "message": _clean_string(
            data.get("communication_summary")
            or _as_dict(data.get("communication")).get("message")
            or previous.get("message")
            or ("Refund completed and parent-safe update recorded." if status == "completed" else "Refund lifecycle update recorded."),
            240,
        ),
        "communicated_at": _clean_string(
            data.get("communicated_at")
            or previous.get("communicated_at")
            or (_now_iso() if status == "completed" else ""),
            40,
        ),
        "intent_only": False,
        "canonical_owner": "LiveUIN TrustPay/Case Ops",
    }


def _refund_settlement(
    *,
    data: Dict[str, Any],
    refund: Dict[str, Any] | None,
    bill: Dict[str, Any],
    amount: int,
    currency: str,
    status: str,
    delayed: bool,
    completed_after: int,
    previous_summary: Dict[str, Any],
) -> Dict[str, Any]:
    refund = refund or {}
    bill_amount = int(bill.get("amount") or 0)
    partial = status == "completed" and completed_after < bill_amount
    return {
        "state": _refund_settlement_state(status, partial=partial, delayed=delayed),
        "expected_settlement_at": _clean_string(
            data.get("expected_settlement_at")
            or _as_dict(data.get("settlement")).get("expected_settlement_at")
            or _as_dict(previous_summary.get("settlement")).get("expected_settlement_at")
            or (_now_iso() if status == "initiated" else ""),
            40,
        ),
        "actual_settlement_at": _clean_string(
            data.get("actual_settlement_at")
            or _as_dict(data.get("settlement")).get("actual_settlement_at")
            or (_now_iso() if status == "completed" else _as_dict(previous_summary.get("settlement")).get("actual_settlement_at")),
            40,
        ),
        "expected_amount": amount,
        "actual_amount": amount if status == "completed" else 0,
        "currency": currency,
        "provider_delay_visible": delayed,
        "provider_failure_visible": status == "failed",
        "dispute_visible": status == "disputed",
        "partial_refund": partial,
        "provider_ref": _clean_string(
            data.get("provider_ref")
            or data.get("provider_refund_ref")
            or _as_dict(refund.get("evidence")).get("provider_ref")
            or "",
            160,
        ),
        "provider": _clean_slug(
            data.get("provider") or _as_dict(refund.get("evidence")).get("provider"),
            "manual",
            ALLOWED_PROVIDERS,
        ),
        "source": _refund_source(data, refund),
    }


def _refund_summary_payload(
    *,
    refund_id: str,
    bill: Dict[str, Any],
    refund: Dict[str, Any] | None,
    amount: int,
    currency: str,
    status: str,
    reason: str,
    data: Dict[str, Any],
    request_meta: Dict[str, str] | None,
    available_before: int,
    completed_before: int,
    completed_after: int,
) -> Dict[str, Any]:
    refund = refund or {}
    previous_summary = _as_dict(refund.get("safe_summary"))
    delayed = _refund_delay_visible(data, status=status, previous_summary=previous_summary)
    calculation = _refund_calculation(
        bill=bill,
        refund=refund,
        amount=amount,
        currency=currency,
        status=status,
        reason=reason,
        available_before=available_before,
        completed_before=completed_before,
        completed_after=completed_after,
    )
    return {
        "summary": _clean_string(data.get("public_summary") or "Refund " + status.replace("_", " ") + " for LiveUIN TrustPay bill.", 220),
        "refund_id": refund_id,
        "bill_id": bill.get("bill_id", ""),
        "intent_id": _clean_id(data.get("intent_id") or refund.get("intent_id"), 96),
        "case_id": bill.get("case_id", ""),
        "amount": amount,
        "currency": currency,
        "status": status,
        "reason": reason,
        "source": _refund_source(data, refund),
        "ledger_reversal_status": _clean_slug(
            data.get("ledger_reversal_status") or previous_summary.get("ledger_reversal_status"),
            "recorded" if status == "completed" else "pending_liveledger_reversal",
            {"pending_liveledger_reversal", "queued_for_liveledger", "recorded", "not_required"},
        ),
        "tenant_payment_received_at": _clean_string(data.get("tenant_payment_received_at") or previous_summary.get("tenant_payment_received_at"), 40),
        "parent_safe_status": "refund_" + status,
        "provider_role": "processor_adapter_or_manual_evidence_only",
        "payment_execution_performed": False,
        "bank_file_created": False,
        "canonical_owner": "LiveUIN TrustPay/LiveLedger",
        "previous_status": _clean_slug(previous_summary.get("status"), "", max_length=80),
        "transition_note": _clean_string(data.get("note") or data.get("transition_note"), 240),
        "status_group": _refund_status_group(status, delayed=delayed),
        "calculation": calculation,
        "approval": _refund_approval(data=data, request_meta=request_meta, status=status, previous_summary=previous_summary),
        "settlement": _refund_settlement(
            data=data,
            refund=refund,
            bill=bill,
            amount=amount,
            currency=currency,
            status=status,
            delayed=delayed,
            completed_after=completed_after,
            previous_summary=previous_summary,
        ),
        "communication": _refund_communication(data=data, status=status, delayed=delayed, previous_summary=previous_summary),
        "escalation": _as_dict(previous_summary.get("escalation")),
    }


