def _payment_summary(
    payments: List[Dict[str, Any]],
    exceptions: List[Dict[str, Any]],
    refunds: List[Dict[str, Any]] | None = None,
) -> Dict[str, Any]:
    refunds = refunds or []
    paid = [item for item in payments if str(item.get("status") or "") in {"paid", "received", "succeeded", "reconciled"}]
    pending = [item for item in payments if str(item.get("status") or "") in {"unpaid", "pending", "intent_created", "created"}]
    refund_like = [
        item
        for item in payments
        if str(item.get("status") or "") in {"refunded", "partially_refunded"}
    ]
    premium_payments = [item for item in payments if _as_dict(item.get("premium_finance")).get("premium_lane") is True]
    partner_collected_payments = [
        item
        for item in premium_payments
        if _as_dict(item.get("premium_finance")).get("partner_collection_mode") == "partner_collected"
    ]
    partner_remittance_pending = [
        item
        for item in partner_collected_payments
        if _as_dict(item.get("premium_finance")).get("partner_remittance_status") == "pending"
    ]
    partner_fee_pending = [
        item
        for item in premium_payments
        if _as_dict(item.get("premium_finance")).get("partner_fee_state") not in {"", "not_required", "paid", "cancelled"}
    ]
    completed_refunds = [item for item in refunds if str(item.get("status") or "") == "completed"]
    amount_due = sum(int(item.get("amount") or 0) for item in pending if item.get("canonical") is True)
    amount_paid = sum(int(item.get("amount") or 0) for item in paid if item.get("canonical") is True)
    amount_refunded = sum(int(item.get("amount") or 0) for item in completed_refunds if item.get("canonical") is True)
    return {
        "payment_count": len(payments),
        "canonical_payment_count": len([item for item in payments if item.get("canonical") is True]),
        "transport_payment_count": len([item for item in payments if item.get("canonical") is False]),
        "paid_count": len(paid),
        "pending_count": len(pending),
        "refund_count": len(refunds),
        "completed_refund_count": len(completed_refunds),
        "refunded_payment_count": len(refund_like),
        "premium_payment_count": len(premium_payments),
        "partner_collected_payment_count": len(partner_collected_payments),
        "partner_remittance_pending_count": len(partner_remittance_pending),
        "partner_fee_pending_count": len(partner_fee_pending),
        "open_exception_count": len([item for item in exceptions if item.get("status") == "open"]),
        "amount_due": amount_due,
        "amount_paid": amount_paid,
        "amount_refunded": amount_refunded,
        "currency": "SGD",
        "source": "liveuin_trustpay",
        "canonical": True,
    }


