def _price_entry(entries: Dict[str, Any], price_key: str) -> Dict[str, Any]:
    entry = _as_dict(entries.get(price_key))
    amount = _bounded_int(entry.get("amount"), 0)
    currency = _clean_string(entry.get("currency"), 12).upper()
    if amount <= 0 or not currency:
        return {}
    return {"amount": amount, "currency": currency, "label": _clean_string(entry.get("label"), 120)}


def create_price_book(payload: Dict[str, Any], request_meta: Dict[str, str] | None = None) -> Dict[str, Any]:
    """Create an immutable commercial price book; edits require a new id/version."""
    if not isinstance(payload, dict):
        return error("invalid_payload")
    data = {**_as_dict(payload.get("price_book") or payload.get("data")), **payload}
    workspace_id = _workspace_id(data)
    price_book_id = _clean_id(data.get("price_book_id"), 96) or "pricebook_" + uuid.uuid4().hex[:16]
    version = _clean_id(data.get("version"), 48)
    if not version:
        return error("price_book_version_required")
    if store.get_price_book(price_book_id, workspace_id):
        return error("price_book_immutable", 409, price_book_id=price_book_id)
    currency = _clean_string(data.get("currency") or "SGD", 12).upper()
    raw_entries = _as_dict(data.get("entries"))
    entries: Dict[str, Any] = {}
    for raw_key, raw_entry in raw_entries.items():
        key = _clean_slug(raw_key, "", max_length=80)
        entry = _as_dict(raw_entry)
        amount = _bounded_int(entry.get("amount"), 0)
        entry_currency = _clean_string(entry.get("currency") or currency, 12).upper()
        if key and amount > 0 and entry_currency == currency:
            entries[key] = {"amount": amount, "currency": entry_currency, "label": _clean_string(entry.get("label"), 120)}
    if not entries:
        return error("price_book_entries_required")
    approved_by = _clean_id(data.get("approved_by"), 96)
    if not approved_by:
        return error("price_book_approver_required")
    price_book = store.insert_price_book(
        {
            "price_book_id": price_book_id,
            "workspace_id": workspace_id,
            "country_code": _clean_string(data.get("country_code") or "SG", 12).upper(),
            "currency": currency,
            "version": version,
            "status": "active",
            "entries": entries,
            "metadata": {
                **_as_dict(_redact(data.get("metadata") or {})),
                "approved_by": approved_by,
                "immutable": True,
                "canonical_owner": "LiveUIN TrustPay/LiveLedger",
            },
        }
    )
    event_id = _append_event(
        event_type="price_book.created", workspace_id=workspace_id,
        payload={"price_book_id": price_book_id, "version": version, "entry_keys": list(entries)}, request_meta=request_meta,
    )
    return _envelope(workspace_id, "price_book_created", event_id=event_id, price_book=price_book)


