def create_validation_override(payload: Dict[str, Any], request_meta: Dict[str, str] | None = None) -> Dict[str, Any]:
    """Create a time-bound S$0.10 validation-only override without changing a price book."""
    if not isinstance(payload, dict):
        return error("invalid_payload")
    data = {**_as_dict(payload.get("validation_override") or payload.get("data")), **payload}
    workspace_id = _workspace_id(data)
    price_book_id = _clean_id(data.get("price_book_id"), 96)
    price_book = store.get_price_book(price_book_id, workspace_id)
    if not price_book:
        return error("price_book_not_found", 404)
    provider = _clean_slug(data.get("provider"), "stripe", ALLOWED_PROVIDERS)
    financial_leg = _clean_slug(data.get("financial_leg"), "deposit", ALLOWED_FINANCIAL_LEGS)
    environment = _clean_slug(data.get("environment"), "sandbox", ALLOWED_VALIDATION_ENVIRONMENTS)
    currency = _clean_string(data.get("currency") or price_book.get("currency") or "SGD", 12).upper()
    if currency != "SGD" or _bounded_int(data.get("amount"), 10) != 10:
        return error("validation_override_must_be_sgd_ten_cents")
    country_code = _clean_string(data.get("country_code") or price_book.get("country_code") or "SG", 12).upper()
    method = _clean_slug(data.get("method"), "card", ALLOWED_METHODS)
    if environment == "live":
        sandbox_passed = any(
            item.get("price_book_id") == price_book_id
            and item.get("provider") == provider
            and item.get("financial_leg") == financial_leg
            and item.get("environment") == "sandbox"
            and item.get("status") == "passed"
            for item in store.list_validation_overrides(workspace_id, status="passed", limit=200)
        )
        if not sandbox_passed:
            return error("sandbox_validation_required", 409)
    rail = payment_rail.resolve_rail(provider, country_code=country_code, currency=currency, method=method, financial_leg=financial_leg, environment=environment)
    if not rail.get("ok"):
        return error("payment_rail_not_available", 409, rail=rail)
    approved_by = _clean_id(data.get("approved_by"), 96)
    test_case_id = _clean_id(data.get("test_case_id"), 96)
    expires_at = _bounded_int(data.get("expires_at"), 0)
    if not approved_by or not test_case_id or expires_at <= _now():
        return error("validation_override_approval_test_case_and_future_expiry_required")
    override_id = _clean_id(data.get("override_id"), 96) or "validation_" + uuid.uuid4().hex[:16]
    override = store.upsert_validation_override(
        {
            "override_id": override_id, "workspace_id": workspace_id, "price_book_id": price_book_id,
            "provider": provider, "financial_leg": financial_leg, "environment": environment,
            "amount": 10, "currency": "SGD", "test_case_id": test_case_id, "approved_by": approved_by,
            "expires_at": expires_at, "status": "active",
            "metadata": {"method": method, "country_code": country_code, "normal_price_preserved": True, "canonical_owner": "LiveUIN TrustPay/LiveLedger"},
        }
    )
    event_id = _append_event(
        event_type="payment.validation_override_created", workspace_id=workspace_id, provider=provider,
        status="active", amount=10, currency="SGD",
        payload={"override_id": override_id, "financial_leg": financial_leg, "environment": environment, "expires_at": expires_at}, request_meta=request_meta,
    )
    return _envelope(workspace_id, "validation_override_created", event_id=event_id, validation_override=override)


def resolve_price(payload: Dict[str, Any]) -> Dict[str, Any]:
    if not isinstance(payload, dict):
        return error("invalid_payload")
    workspace_id = _workspace_id(payload)
    price_book_id = _clean_id(payload.get("price_book_id"), 96)
    price_key = _clean_slug(payload.get("price_key") or payload.get("financial_leg"), "", max_length=80)
    price_book = store.get_price_book(price_book_id, workspace_id)
    if not price_book:
        return error("price_book_not_found", 404)
    entry = _price_entry(_as_dict(price_book.get("entries")), price_key)
    if not entry:
        return error("price_book_entry_not_found", 404, price_key=price_key)
    provider = _clean_slug(payload.get("provider"), "", ALLOWED_PROVIDERS)
    financial_leg = _clean_slug(payload.get("financial_leg") or price_key, "", ALLOWED_FINANCIAL_LEGS)
    environment = _clean_slug(payload.get("environment"), "", ALLOWED_VALIDATION_ENVIRONMENTS)
    override: Dict[str, Any] = {}
    if provider and financial_leg and environment:
        override = store.find_active_validation_override(workspace_id, price_book_id, provider, financial_leg, environment, _now())
    amount = int(override.get("amount") or entry["amount"])
    currency = str(override.get("currency") or entry["currency"])
    return _envelope(
        workspace_id, "price_resolved", price_book_id=price_book_id, price_key=price_key,
        amount=amount, currency=currency, normal_amount=entry["amount"], normal_currency=entry["currency"],
        price_book_version=str(price_book.get("version") or ""),
        validation_override_id=override.get("override_id", ""), validation_override_applied=bool(override),
        normal_price_preserved=True,
    )


def create_bill(payload: Dict[str, Any], request_meta: Dict[str, str] | None = None) -> Dict[str, Any]:
    if not isinstance(payload, dict):
        return error("invalid_payload")
    data = {**_as_dict(payload.get("bill") or payload.get("data")), **payload}
    workspace_id = _workspace_id(data)
    guard = _require_case(data.get("case_id"), workspace_id)
    if guard.get("ok") is False:
        return guard
    booking_id = _clean_id(data.get("booking_id"), 96)
    booking_guard = _require_booking(booking_id, workspace_id, guard["case_id"])
    if booking_guard.get("ok") is False:
        return booking_guard
    booking_record = _as_dict(booking_guard.get("booking"))
    booking_version_guard = booking_svc.g32_offer_version_gate_for_booking_record(booking_record, workspace_id)
    if booking_version_guard.get("ok") is False:
        return booking_version_guard
    compliance_gate = agreement_svc.g35_payment_ready_gate_for_booking(booking_id, workspace_id)
    if compliance_gate.get("ok") is False:
        return compliance_gate
    booking_offer_binding = _as_dict(booking_version_guard.get("offer_version_binding"))
    raw_metadata = _as_dict(data.get("metadata"))
    purpose_type = _clean_slug(data.get("purpose_type") or data.get("type"), "deposit", ALLOWED_PURPOSES)
    pricing: Dict[str, Any] = {}
    price_book_id = _clean_id(data.get("price_book_id") or raw_metadata.get("price_book_id"), 96)
    price_key = _clean_slug(data.get("price_key") or raw_metadata.get("price_key"), "", max_length=80)
    if price_book_id:
        resolved_price = resolve_price(
            {
                "workspace_id": workspace_id,
                "price_book_id": price_book_id,
                "price_key": price_key or purpose_type,
                "provider": data.get("provider") or raw_metadata.get("provider"),
                "financial_leg": data.get("financial_leg") or raw_metadata.get("financial_leg") or purpose_type,
                "environment": data.get("environment") or raw_metadata.get("environment"),
            }
        )
        if resolved_price.get("ok") is False:
            return resolved_price
        supplied_amount = _bounded_int(data.get("amount"), 0)
        if supplied_amount and supplied_amount != int(resolved_price["amount"]):
            return error("price_book_amount_mismatch", 409, expected_amount=resolved_price["amount"])
        amount = int(resolved_price["amount"])
        currency = str(resolved_price["currency"])
        pricing = {
            "price_book_id": price_book_id,
            "price_book_version": _clean_id(resolved_price.get("price_book_version"), 48),
            "price_key": resolved_price["price_key"],
            "normal_amount": resolved_price["normal_amount"],
            "normal_currency": resolved_price["normal_currency"],
            "validation_override_id": resolved_price["validation_override_id"],
            "validation_override_applied": resolved_price["validation_override_applied"],
            "normal_price_preserved": True,
        }
    else:
        amount = _bounded_int(data.get("amount"), 0)
        currency = _clean_string(data.get("currency") or "SGD", 12).upper()
    if amount <= 0:
        return error("bill_amount_required")
    finance_enforcement = _finance_enforcement(guard["case_id"], workspace_id, purpose_type, {**raw_metadata, **data})
    if finance_enforcement.get("ok") is False:
        return finance_enforcement
    if finance_enforcement.get("blocked") is True:
        return error(
            "finance_runtime_pending_review",
            409,
            state=finance_enforcement.get("state") or "pending_review",
            reason_codes=_as_list(finance_enforcement.get("reason_codes")),
            runtime=finance_enforcement,
        )
    money_map_built = _g36_build_money_map(
        workspace_id=workspace_id,
        case_id=guard["case_id"],
        booking_id=booking_id,
        purpose_type=purpose_type,
        purpose_id=_clean_id(data.get("purpose_id") or booking_id, 96),
        payer_id=_clean_id(data.get("payer_id"), 96),
        amount=amount,
        currency=currency,
        due_at=_bounded_int(data.get("due_at"), 0),
        data=data,
        raw_metadata=raw_metadata,
        booking_record=booking_record,
        booking_offer_binding=booking_offer_binding,
        pricing=pricing,
        finance_enforcement=finance_enforcement,
    )
    if money_map_built.get("ok") is False:
        return money_map_built
    current_money_map = _g36_money_map_current(booking_id, purpose_type, workspace_id) if booking_id else {}
    money_map_payload = _as_dict(money_map_built.get("payload"))
    current_money_map_projection = _g36_projection(current_money_map) if current_money_map else {}
    bill_id = _clean_id(data.get("bill_id"), 96) or "bill_" + uuid.uuid4().hex[:16]
    bill_record = {
        "bill_id": bill_id,
        "workspace_id": workspace_id,
        "case_id": guard["case_id"],
        "booking_id": booking_id,
        "purpose_type": purpose_type,
        "purpose_id": _clean_id(data.get("purpose_id") or booking_id, 96),
        "payer_id": _clean_id(data.get("payer_id"), 96),
        "amount": amount,
        "currency": currency,
        "due_at": _bounded_int(data.get("due_at"), 0),
        "status": _clean_slug(data.get("status"), "unpaid", ALLOWED_BILL_STATUS),
        "description": _clean_string(data.get("description") or data.get("label"), 220),
        "receipt": {},
        "metadata": {
            **raw_metadata,
            "property_id": _clean_id(data.get("property_id") or raw_metadata.get("property_id"), 96),
            "master_property_id": _clean_id(data.get("master_property_id") or raw_metadata.get("master_property_id"), 96),
            "room_id": _clean_id(data.get("room_id") or raw_metadata.get("room_id"), 96),
            "issuer_id": _clean_id(data.get("issuer_id") or raw_metadata.get("issuer_id"), 96),
            "country_code": _clean_string(data.get("country_code") or raw_metadata.get("country_code"), 24).upper(),
            "runtime": {
                "case_id": guard["case_id"],
                "state": _clean_slug(finance_enforcement.get("state"), "pending_review", max_length=40),
                "runtime_activation_record_id": _clean_id(finance_enforcement.get("runtime_activation_record_id"), 96),
                "approved_finance_snapshot_id": _clean_id(finance_enforcement.get("approved_finance_snapshot_id"), 96),
                "payer_liability_policy_id": _clean_id(finance_enforcement.get("payer_liability_policy_id"), 96),
                "billing_cycle_policy_id": _clean_id(finance_enforcement.get("billing_cycle_policy_id"), 96),
                "payment_mandate_policy_id": _clean_id(finance_enforcement.get("payment_mandate_policy_id"), 96),
                "finance_classification_snapshot_id": _clean_id(finance_enforcement.get("finance_classification_snapshot_id"), 96),
                "finance_classification_version_id": _clean_string(finance_enforcement.get("finance_classification_version_id"), 160),
                "finance_classification_hash": _clean_string(finance_enforcement.get("finance_classification_hash"), 160),
                "utility_evidence_pack_id": _clean_id(finance_enforcement.get("utility_evidence_pack_id"), 96),
                "utility_allocation_snapshot_id": _clean_id(finance_enforcement.get("utility_allocation_snapshot_id"), 96),
                "wallet_mode": _clean_slug(finance_enforcement.get("wallet_mode"), "read_safe", max_length=40),
                "reason_codes": _as_list(finance_enforcement.get("reason_codes")),
                "liable_payer": _as_dict(finance_enforcement.get("liable_payer")),
                "billing_behavior": _as_dict(finance_enforcement.get("billing_behavior")),
                "mandate_behavior": _as_dict(finance_enforcement.get("mandate_behavior")),
            },
            "canonical_owner": "LiveUIN TrustPay/LiveLedger",
            "payment_provider_truth_used": False,
            "pricing": pricing,
            "offer_version_binding": booking_offer_binding,
            "money_map": {
                **money_map_payload,
                "money_map_version_id": current_money_map_projection.get("money_map_version_id", ""),
            },
            **_premium_finance_metadata(data, raw_metadata, bill_currency=currency),
        },
    }
    existing_booking_bill = store.get_active_bill_for_booking(booking_id, purpose_type, workspace_id) if booking_id else {}
    if existing_booking_bill:
        existing_binding = _bill_offer_version_binding(existing_booking_bill)
        if (
            existing_binding.get("offer_version_id") != booking_offer_binding.get("offer_version_id")
            or existing_binding.get("offer_version_hash") != booking_offer_binding.get("offer_version_hash")
        ):
            return error("booking_offer_version_changed_requires_renewed_decision", 409, bill_id=existing_booking_bill.get("bill_id", ""))
        existing_money_map = _bill_money_map(existing_booking_bill)
        if _money_map_hash(existing_money_map) != _clean_string(money_map_payload.get("money_map_hash"), 160):
            return error("payment_obligation_changed_requires_renewed_decision", 409, bill_id=existing_booking_bill.get("bill_id", ""))
        if int(existing_booking_bill.get("amount") or 0) != amount or str(existing_booking_bill.get("currency") or "SGD") != currency:
            return error("booking_payment_obligation_mismatch", 409, bill_id=existing_booking_bill.get("bill_id", ""))
        return _envelope(workspace_id, "bill_reused", bill=_bill_safe(existing_booking_bill), reused=True)

    stored_money_map = _g36_store_money_map(booking_id, purpose_type, workspace_id, money_map_payload, request_meta)
    if stored_money_map.get("ok") is False:
        return stored_money_map
    bill_record["metadata"]["money_map"] = _as_dict(stored_money_map.get("money_map"))
    bill_claim = store.claim_bill_for_booking_atomic(bill_record) if booking_id else {"created": True, "bill": store.upsert_bill(bill_record)}
    bill = bill_claim.get("bill") if isinstance(bill_claim.get("bill"), dict) else {}
    if booking_id and bill_claim.get("created") is not True:
        existing_binding = _bill_offer_version_binding(bill)
        if (
            existing_binding.get("offer_version_id") != booking_offer_binding.get("offer_version_id")
            or existing_binding.get("offer_version_hash") != booking_offer_binding.get("offer_version_hash")
        ):
            return error("booking_offer_version_changed_requires_renewed_decision", 409, bill_id=bill.get("bill_id", ""))
        existing_money_map = _bill_money_map(bill)
        if _money_map_hash(existing_money_map) != _clean_string(money_map_payload.get("money_map_hash"), 160):
            return error("payment_obligation_changed_requires_renewed_decision", 409, bill_id=bill.get("bill_id", ""))
        if int(bill.get("amount") or 0) != amount or str(bill.get("currency") or "SGD") != currency:
            return error("booking_payment_obligation_mismatch", 409, bill_id=bill.get("bill_id", ""))
        return _envelope(workspace_id, "bill_reused", bill=_bill_safe(bill), reused=True)
    event_id = _append_event(
        event_type="bill.created",
        workspace_id=workspace_id,
        bill_id=bill_id,
        case_id=guard["case_id"],
        booking_id=booking_id,
        status=bill.get("status", "unpaid"),
        amount=amount,
        currency=bill.get("currency", "SGD"),
        payload={"purpose_type": bill.get("purpose_type", ""), "amount": amount},
        request_meta=request_meta,
    )
    return _envelope(workspace_id, "bill_created", event_id=event_id, bill=_bill_safe(bill))


def get_bill(bill_id: str, workspace_id: str = DEFAULT_WORKSPACE_ID) -> Dict[str, Any]:
    workspace_id = _clean_id(workspace_id, 96) or DEFAULT_WORKSPACE_ID
    bill_id = _clean_id(bill_id, 96)
    if not bill_id:
        return error("bill_id_required")
    bill = store.get_bill(bill_id, workspace_id)
    if not bill:
        return error("bill_not_found", 404)
    intents = [_intent_safe(item) for item in store.list_intents_for_bill(bill_id, workspace_id)]
    return _envelope(workspace_id, "bill_loaded", bill=_bill_safe(bill), intents=intents)


def list_bills(workspace_id: str = DEFAULT_WORKSPACE_ID, status: str = "", limit: int = 50) -> Dict[str, Any]:
    workspace_id = _clean_id(workspace_id, 96) or DEFAULT_WORKSPACE_ID
    status = _clean_slug(status, "", ALLOWED_BILL_STATUS) if status else ""
    bills = store.list_bills(workspace_id, status, limit)
    return _envelope(workspace_id, "bills_loaded", status_filter=status, bills=[_bill_safe(item) for item in bills], bill_count=len(bills))


def create_payment_intent(payload: Dict[str, Any], request_meta: Dict[str, str] | None = None) -> Dict[str, Any]:
    if not isinstance(payload, dict):
        return error("invalid_payload")
    data = {**_as_dict(payload.get("intent") or payload.get("data")), **payload}
    workspace_id = _workspace_id(data)
    bill_id = _clean_id(data.get("bill_id"), 96)
    bill = store.get_bill(bill_id, workspace_id)
    if not bill:
        return error("bill_not_found", 404)
    bill_offer_binding = _bill_offer_version_binding(bill)
    if not bill_offer_binding.get("offer_version_id") or not bill_offer_binding.get("offer_version_hash"):
        return error("bill_offer_version_binding_required", 409, bill_id=bill_id)
    if str(bill.get("booking_id") or ""):
        booking_version_guard = booking_svc.g32_offer_version_gate_for_booking(str(bill.get("booking_id") or ""), workspace_id)
        if booking_version_guard.get("ok") is False:
            return booking_version_guard
        compliance_gate = agreement_svc.g35_payment_ready_gate_for_booking(str(bill.get("booking_id") or ""), workspace_id)
        if compliance_gate.get("ok") is False:
            return compliance_gate
        current_offer_binding = _as_dict(booking_version_guard.get("offer_version_binding"))
        if (
            bill_offer_binding.get("offer_version_id") != current_offer_binding.get("offer_version_id")
            or bill_offer_binding.get("offer_version_hash") != current_offer_binding.get("offer_version_hash")
        ):
            return error("payment_offer_version_changed_requires_renewed_decision", 409, bill_id=bill_id)
        money_map_guard = _g36_bill_current_guard(bill, workspace_id)
        if money_map_guard.get("ok") is False:
            return money_map_guard
    amount = _bounded_int(data.get("amount"), int(bill.get("amount") or 0))
    if amount <= 0:
        return error("intent_amount_required")
    raw_metadata = _as_dict(_redact(data.get("metadata") or {}))
    requested_runtime_reference = _runtime_reference(
        {
            **raw_metadata,
            "runtime_reference": _as_dict(data.get("runtime_reference")),
            "runtime": _as_dict(data.get("runtime")),
        }
    )
    actor_role = _clean_slug(_as_dict(request_meta).get("access_actor_role"), "", max_length=80)
    resident_actor = actor_role in RESIDENT_PAYMENT_INTENT_ROLES
    method = _clean_slug(data.get("method"), "paynow_qr", ALLOWED_METHODS)
    provider = _clean_slug(data.get("provider"), "manual", ALLOWED_PROVIDERS)
    bill_pricing = _as_dict(_as_dict(bill.get("metadata")).get("pricing"))
    financial_leg = _clean_slug(
        data.get("financial_leg") or raw_metadata.get("financial_leg") or bill_pricing.get("price_key"),
        "", ALLOWED_FINANCIAL_LEGS,
    )
    validation_environment = _clean_slug(
        data.get("validation_environment") or data.get("environment") or raw_metadata.get("validation_environment") or raw_metadata.get("environment"),
        "", ALLOWED_VALIDATION_ENVIRONMENTS,
    )
    rail_selected = bool(financial_leg or validation_environment or bill_pricing.get("validation_override_id"))
    rail: Dict[str, Any] = {}
    if rail_selected:
        if not financial_leg or not validation_environment:
            return error("financial_leg_and_validation_environment_required")
        rail = payment_rail.resolve_rail(
            provider,
            country_code=_clean_string(_as_dict(bill.get("metadata")).get("country_code") or "SG", 12).upper(),
            currency=_clean_string(data.get("currency") or bill.get("currency") or "SGD", 12).upper(),
            method=method,
            financial_leg=financial_leg,
            environment=validation_environment,
        )
        if not rail.get("ok"):
            return error("payment_rail_not_available", 409, rail=rail)
    if resident_actor:
        bill_case_id = _clean_id(bill.get("case_id"), 96)
        requested_case_id = _clean_id(data.get("case_id"), 96)
        if not requested_case_id or requested_case_id != bill_case_id:
            return error("resident_case_scope_required", 403, case_id=bill_case_id)
        if amount != int(bill.get("amount") or 0):
            return error("resident_intent_amount_must_match_bill", 409, bill_id=bill_id, case_id=bill_case_id)
        bill_status = _clean_slug(bill.get("status"), "", max_length=40)
        if bill_status not in {"unpaid", "pending", "partially_paid"}:
            return error("resident_bill_not_payable", 409, bill_id=bill_id, case_id=bill_case_id, status=bill_status)
        runtime_reference = _runtime_reference(_as_dict(bill.get("metadata")))
        runtime_state = _clean_slug(runtime_reference.get("state"), "pending_review", max_length=40)
        wallet_mode = _clean_slug(runtime_reference.get("wallet_mode"), "read_safe", max_length=40)
        for field in (
            "runtime_activation_record_id",
            "approved_finance_snapshot_id",
            "payer_liability_policy_id",
            "billing_cycle_policy_id",
            "payment_mandate_policy_id",
            "finance_classification_snapshot_id",
            "utility_evidence_pack_id",
            "utility_allocation_snapshot_id",
        ):
            requested_value = _clean_id(requested_runtime_reference.get(field), 96)
            expected_value = _clean_id(runtime_reference.get(field), 96)
            if requested_value and expected_value and requested_value != expected_value:
                return error(
                    "resident_runtime_reference_mismatch",
                    409,
                    bill_id=bill_id,
                    case_id=bill_case_id,
                    runtime_field=field,
                    requested_value=requested_value,
                    expected_value=expected_value,
                )
        if runtime_state == "blocked" or wallet_mode == "hidden":
            return error(
                "resident_wallet_action_blocked",
                409,
                bill_id=bill_id,
                case_id=bill_case_id,
                runtime_state=runtime_state,
                wallet_mode=wallet_mode,
                reason_codes=_as_list(runtime_reference.get("reason_codes")),
            )
        if method not in RESIDENT_PAYMENT_INTENT_METHODS:
            return error("resident_payment_method_not_allowed", 409, method=method)
        if provider not in RESIDENT_PAYMENT_INTENT_PROVIDERS:
            return error("resident_payment_provider_not_allowed", 409, provider=provider)
    try:
        from . import core_finance_runtime_service as finance_runtime_svc
    except ImportError:  # pragma: no cover
        import core_finance_runtime_service as finance_runtime_svc  # type: ignore
    bill_runtime_reference = _runtime_reference(_as_dict(bill.get("metadata")))
    finance_classification_guard = finance_runtime_svc.validate_finance_intent_classification(
        _clean_id(bill.get("case_id"), 96),
        workspace_id,
        purpose_type=_clean_slug(bill.get("purpose_type"), "deposit", max_length=80),
        provider=provider,
        method=method,
        validation_environment=validation_environment or "sandbox",
        bill_runtime_reference=_as_dict(_bill_money_map(bill)).get("runtime_reference"),
        bill_metadata=_as_dict(bill.get("metadata")),
    )
    if finance_classification_guard.get("ok") is False:
        return finance_classification_guard
    resolved_runtime_reference = {
        **bill_runtime_reference,
        **{
            key: value
            for key, value in requested_runtime_reference.items()
            if value not in ("", [], {})
        },
    }
    existing_intent = store.get_active_intent_for_bill(bill_id, provider, workspace_id)
    if existing_intent:
        existing_amount = int(existing_intent.get("amount") or 0)
        existing_currency = str(existing_intent.get("currency") or "SGD")
        existing_provider_ref = _clean_string(existing_intent.get("provider_ref"), 160)
        requested_provider_ref = _clean_string(data.get("provider_ref") or data.get("provider_intent_id"), 160)
        if existing_amount != amount or existing_currency != _clean_string(data.get("currency") or bill.get("currency") or "SGD", 12).upper():
            return error("payment_intent_obligation_mismatch", 409, intent_id=existing_intent.get("intent_id", ""))
        if requested_provider_ref and existing_provider_ref and requested_provider_ref != existing_provider_ref:
            return error("payment_intent_provider_reference_mismatch", 409, intent_id=existing_intent.get("intent_id", ""))
        return _envelope(workspace_id, "payment_intent_reused", bill=_bill_safe(bill), intent=_intent_safe(existing_intent), reused=True)

    intent_id = _clean_id(data.get("intent_id"), 96) or "intent_" + uuid.uuid4().hex[:16]
    provider_ref = _clean_string(data.get("provider_ref") or data.get("provider_intent_id"), 160)
    intent_record = {
        "intent_id": intent_id,
        "workspace_id": workspace_id,
        "bill_id": bill_id,
        "case_id": bill.get("case_id", ""),
        "booking_id": bill.get("booking_id", ""),
        "payer_id": _clean_id(data.get("payer_id") or bill.get("payer_id"), 96),
        "method": method,
        "provider": provider,
        "provider_ref": provider_ref,
        "amount": amount,
        "currency": _clean_string(data.get("currency") or bill.get("currency") or "SGD", 12).upper(),
        "status": _clean_slug(data.get("status"), "created", ALLOWED_INTENT_STATUS),
        "checkout_hint": provider + ("_checkout_ready" if data.get("checkout_url") or data.get("provider_checkout_url") else "_manual"),
        "metadata": {
            **raw_metadata,
            "runtime_reference": resolved_runtime_reference,
            "runtime": resolved_runtime_reference,
            "resident_payment_lane": resident_actor,
            "requested_case_id": _clean_id(data.get("case_id"), 96),
            "provider_role": "processor_adapter_only",
            "raw_checkout_url_stored": False,
            "financial_leg": financial_leg,
            "validation_environment": validation_environment,
            "payment_rail": rail.get("rail", {}),
            "validation_override_id": bill_pricing.get("validation_override_id", ""),
            "normal_price_preserved": bool(bill_pricing.get("normal_price_preserved")),
            "offer_version_binding": bill_offer_binding,
            "money_map": _bill_money_map(bill),
            **_premium_finance_metadata(
                data,
                _as_dict(bill.get("metadata")),
                bill_currency=str(data.get("currency") or bill.get("currency") or "SGD"),
            ),
        },
    }
    intent_claim = store.claim_intent_for_bill_atomic(intent_record)
    intent = intent_claim.get("intent") if isinstance(intent_claim.get("intent"), dict) else {}
    if intent_claim.get("created") is not True:
        return _envelope(workspace_id, "payment_intent_reused", bill=_bill_safe(bill), intent=_intent_safe(intent), reused=True)
    if bill.get("status") == "unpaid":
        bill = store.upsert_bill({**bill, "status": "pending", "updated_at": _now()})
    event_id = _append_event(
        event_type="payment.intent_created",
        workspace_id=workspace_id,
        bill_id=bill_id,
        intent_id=intent_id,
        case_id=bill.get("case_id", ""),
        booking_id=bill.get("booking_id", ""),
        provider=provider,
        status=intent.get("status", "created"),
        amount=amount,
        currency=intent.get("currency", "SGD"),
        payload={"provider_ref": provider_ref, "method": intent.get("method", "")},
        request_meta=request_meta,
    )
    _append_case_payment_event(
        case_id=bill.get("case_id", ""),
        workspace_id=workspace_id,
        event_type="payment.intent_created",
        label="Payment intent created",
        detail="A LiveUIN TrustPay payment intent is ready for review.",
        state="pending",
        status_group="deposit_pending" if bill.get("purpose_type") == "deposit" else "",
        request_meta=request_meta,
    )
    return _envelope(workspace_id, "payment_intent_created", event_id=event_id, bill=_bill_safe(bill), intent=_intent_safe(intent))


def _provider_status(payload: Dict[str, Any]) -> str:
    raw = _clean_slug(payload.get("status") or payload.get("provider_status") or payload.get("event_type"), "pending")
    if raw in {"succeeded", "success", "paid", "received", "payment_succeeded", "settled"}:
        return "succeeded"
    if raw in {"failed", "payment_failed", "declined"}:
        return "failed"
    if raw in {"cancelled", "canceled"}:
        return "cancelled"
    if raw in {"expired"}:
        return "expired"
    if raw in {"requires_review", "review"}:
        return "requires_review"
    return "pending"


def record_provider_event(
    intent_id: str,
    payload: Dict[str, Any],
    request_meta: Dict[str, str] | None = None,
) -> Dict[str, Any]:
    if not isinstance(payload, dict):
        return error("invalid_payload")
    workspace_id = _workspace_id(payload)
    intent_id = _clean_id(intent_id or payload.get("intent_id"), 96)
    if not intent_id:
        return error("intent_id_required")
    intent = store.get_intent(intent_id, workspace_id)
    if not intent:
        return error("intent_not_found", 404)
    bill = store.get_bill(intent.get("bill_id", ""), workspace_id)
    if not bill:
        return error("bill_not_found", 404)

    normalized = provider_adapter.normalize_provider_event(
        payload,
        fallback_provider=str(intent.get("provider") or "manual"),
        fallback_amount=int(intent.get("amount") or 0),
        fallback_currency=str(intent.get("currency") or "SGD"),
    )
    if normalized.get("ok") is False:
        return error(str(normalized.get("detail") or "provider_event_normalization_failed"), int(normalized.get("status_code") or 400))
    provider_event = _as_dict(normalized.get("provider_event"))
    provider_status = _provider_status(provider_event)
    provider = _clean_slug(provider_event.get("provider") or intent.get("provider"), intent.get("provider", "manual"), ALLOWED_PROVIDERS)
    amount = _bounded_int(provider_event.get("amount"), int(intent.get("amount") or 0))
    currency = _clean_string(provider_event.get("currency") or intent.get("currency") or "SGD", 12).upper()
    provider_event_id = _clean_id(provider_event.get("provider_event_id") or provider_event.get("event_id"), 120) or "provider_evt_" + uuid.uuid4().hex[:12]
    provider_ref = _clean_string(provider_event.get("provider_ref") or intent.get("provider_ref"), 160)
    duplicate_event = store.get_event_by_provider_event_id(provider_event_id, intent_id, workspace_id)
    if duplicate_event:
        return _envelope(
            workspace_id,
            "provider_event_replayed",
            bill=_bill_safe(bill),
            intent=_intent_safe(intent),
            replay=True,
            provider_event_id=provider_event_id,
        )
    exception: Dict[str, Any] = {}
    bill_status = bill.get("status", "pending")
    intent_status = provider_status
    receipt: Dict[str, Any] = {}
    booking = booking_svc.store.get_booking(str(bill.get("booking_id") or ""), workspace_id) if str(bill.get("booking_id") or "") else {}
    booking_version_guard: Dict[str, Any] = {"ok": True}
    if provider_status == "succeeded" and booking:
        booking_version_guard = booking_svc.g32_offer_version_gate_for_booking_record(booking, workspace_id)

    amount_delta = amount - int(bill.get("amount") or 0)
    currency_mismatch = currency != str(bill.get("currency") or "SGD")
    booking_closed = booking and str(booking.get("status") or "") in {"cancelled", "expired", "failed"}
    if provider_status == "succeeded" and booking_version_guard.get("ok") is False:
        intent_status = "requires_review"
        bill_status = "exception"
        exception = store.upsert_exception(
            {
                "exception_id": "pay_exc_" + uuid.uuid4().hex[:16],
                "workspace_id": workspace_id,
                "case_id": bill.get("case_id", ""),
                "bill_id": bill.get("bill_id", ""),
                "intent_id": intent_id,
                "booking_id": bill.get("booking_id", ""),
                "severity": "high",
                "reason": str(booking_version_guard.get("detail") or "offer_version_changed_requires_renewed_decision"),
                "status": "open",
                "safe_summary": {"summary": "Provider payment arrived for a stale or invalidated offer version decision."},
                "metadata": {"provider": provider, "provider_event_id": provider_event_id},
            }
        )
    elif provider_status == "succeeded" and booking_closed:
        intent_status = "requires_review"
        bill_status = "exception"
        exception = store.upsert_exception(
            {
                "exception_id": "pay_exc_" + uuid.uuid4().hex[:16],
                "workspace_id": workspace_id,
                "case_id": bill.get("case_id", ""),
                "bill_id": bill.get("bill_id", ""),
                "intent_id": intent_id,
                "booking_id": bill.get("booking_id", ""),
                "severity": "high",
                "reason": "orphan_payment_closed_booking",
                "status": "open",
                "safe_summary": {"summary": "Provider payment arrived after the canonical booking path had already closed."},
                "metadata": {"provider": provider, "provider_event_id": provider_event_id, "booking_status": booking.get("status", "")},
            }
        )
    elif provider_status == "succeeded" and (amount_delta != 0 or currency_mismatch):
        intent_status = "requires_review"
        bill_status = "exception"
        exception = store.upsert_exception(
            {
                "exception_id": "pay_exc_" + uuid.uuid4().hex[:16],
                "workspace_id": workspace_id,
                "case_id": bill.get("case_id", ""),
                "bill_id": bill.get("bill_id", ""),
                "intent_id": intent_id,
                "booking_id": bill.get("booking_id", ""),
                "severity": "high",
                "reason": "amount_or_currency_mismatch",
                "status": "open",
                "amount_delta": amount_delta,
                "safe_summary": {
                    "summary": "Provider payment does not match the LiveUIN bill.",
                    "expected_amount": int(bill.get("amount") or 0),
                    "received_amount": amount,
                    "expected_currency": bill.get("currency", "SGD"),
                    "received_currency": currency,
                },
                "metadata": {"provider": provider, "provider_event_id": provider_event_id},
            }
        )
    elif provider_status == "succeeded":
        bill_status = "paid"
        receipt = {
            "receipt_id": "rcpt_" + uuid.uuid4().hex[:16],
            "amount": amount,
            "currency": currency,
            "paid_at": _now_iso(),
            "provider": provider,
            "provider_ref": provider_ref,
            "source": "liveuin_trustpay",
            "canonical": True,
        }
    elif provider_status in {"failed", "cancelled", "expired"}:
        bill_status = "exception"
        exception = store.upsert_exception(
            {
                "exception_id": "pay_exc_" + uuid.uuid4().hex[:16],
                "workspace_id": workspace_id,
                "case_id": bill.get("case_id", ""),
                "bill_id": bill.get("bill_id", ""),
                "intent_id": intent_id,
                "booking_id": bill.get("booking_id", ""),
                "severity": "medium",
                "reason": "provider_" + provider_status,
                "status": "open",
                "safe_summary": {"summary": "Provider returned " + provider_status + " for this payment intent."},
                "metadata": {"provider": provider, "provider_event_id": provider_event_id},
            }
        )
    elif provider_status == "requires_review":
        bill_status = "exception"

    updated_intent = store.upsert_intent(
        {
            **intent,
            "provider": provider,
            "status": intent_status,
            "receipt": receipt or intent.get("receipt") or {},
            "metadata": {
                **_as_dict(intent.get("metadata")),
                "last_provider_event_id": provider_event_id,
                "last_provider_payload_shape": provider_event.get("provider_payload_shape", ""),
                "provider_adapter_schema": provider_adapter.SCHEMA_VERSION,
                "provider_role": "processor_adapter_only",
                **_premium_finance_metadata(
                    payload,
                    _as_dict(intent.get("metadata")),
                    bill_currency=currency,
                    payment_received_at=_clean_string(receipt.get("paid_at"), 40),
                ),
            },
            "updated_at": _now(),
        }
    )
    updated_bill = store.upsert_bill(
        {
            **bill,
            "status": bill_status,
            "receipt": receipt or bill.get("receipt") or {},
            "metadata": {
                **_as_dict(bill.get("metadata")),
                "last_provider": provider,
                "last_provider_payload_shape": provider_event.get("provider_payload_shape", ""),
                "provider_adapter_schema": provider_adapter.SCHEMA_VERSION,
                "provider_truth_used": False,
                **_premium_finance_metadata(
                    payload,
                    _as_dict(bill.get("metadata")),
                    bill_currency=currency,
                    payment_received_at=_clean_string(receipt.get("paid_at"), 40),
                ),
            },
            "updated_at": _now(),
        }
    )
    event_id = _append_event(
        event_type="provider.event_received",
        workspace_id=workspace_id,
        bill_id=bill.get("bill_id", ""),
        intent_id=intent_id,
        case_id=bill.get("case_id", ""),
        booking_id=bill.get("booking_id", ""),
        provider=provider,
        provider_event_id=provider_event_id,
        status=intent_status,
        amount=amount,
        currency=currency,
        payload={
            "provider_event": provider_event,
            "provider_adapter": normalized.get("provider_adapter", {}),
            "raw_provider_payload_stored": False,
        },
        request_meta=request_meta,
    )
    validation_record: Dict[str, Any] = {}
    validation_override_id = _clean_id(_as_dict(updated_intent.get("metadata")).get("validation_override_id"), 96)
    if validation_override_id:
        validation_record = store.upsert_validation_record(
            {
                "validation_id": "validation_record_" + uuid.uuid4().hex[:16],
                "workspace_id": workspace_id,
                "override_id": validation_override_id,
                "provider": provider,
                "financial_leg": _clean_slug(_as_dict(updated_intent.get("metadata")).get("financial_leg"), "deposit", ALLOWED_FINANCIAL_LEGS),
                "environment": _clean_slug(_as_dict(updated_intent.get("metadata")).get("validation_environment"), "sandbox", ALLOWED_VALIDATION_ENVIRONMENTS),
                "bill_id": bill.get("bill_id", ""),
                "intent_id": intent_id,
                "provider_ref": provider_ref,
                "status": "provider_event_received" if intent_status == "succeeded" else "failed",
                "metadata": {
                    "provider_event_id": provider_event_id,
                    "provider_event_status": intent_status,
                    "ledger_link_event_id": event_id,
                    "receipt_present": bool(receipt),
                    "canonical_owner": "LiveUIN TrustPay/LiveLedger",
                },
            }
        )
    if bill_status == "paid":
        _append_case_payment_event(
            case_id=bill.get("case_id", ""),
            workspace_id=workspace_id,
            event_type="payment.received",
            label="Payment received",
            detail="LiveUIN TrustPay marked the payment as received.",
            state="complete",
            request_meta=request_meta,
        )
    return _envelope(
        workspace_id,
        "provider_event_recorded",
        event_id=event_id,
        bill=_bill_safe(updated_bill),
        intent=_intent_safe(updated_intent),
        exception=_exception_safe(exception) if exception else {},
        validation_record=validation_record,
        provider_adapter=normalized.get("provider_adapter", {}),
    )


def record_verified_provider_webhook(verified_webhook: Dict[str, Any], request_meta: Dict[str, str] | None = None) -> Dict[str, Any]:
    """Correlate an already signature-verified provider event to a canonical intent.

    A webhook is transport evidence, not payment truth. Unmatched events are
    acknowledged so Stripe does not retry them, but cannot mutate TrustPay.
    """
    event = _as_dict(verified_webhook.get("provider_event"))
    provider = _clean_slug(event.get("provider") or verified_webhook.get("provider"), "other", ALLOWED_PROVIDERS)
    provider_ref = _clean_string(event.get("provider_ref"), 160)
    workspace_id = _clean_id(event.get("workspace_id") or DEFAULT_WORKSPACE_ID, 96) or DEFAULT_WORKSPACE_ID
    if not provider_ref:
        return _envelope(workspace_id, "verified_provider_event_unmatched", matched=False, reason="provider_reference_missing")

    intent = store.get_intent_by_provider_ref(provider, provider_ref, workspace_id)
    if not intent:
        return _envelope(
            workspace_id,
            "verified_provider_event_unmatched",
            matched=False,
            provider=provider,
            provider_ref=provider_ref,
            reason="no_canonical_intent_for_provider_reference",
        )

    provider_payload = {
        "provider": provider,
        "provider_event_id": event.get("provider_event_id") or "",
        "event_type": event.get("event_type") or "provider.event",
        "status": event.get("status") or "pending",
        "provider_status": event.get("provider_status") or event.get("status") or "pending",
        "amount": event.get("amount") or 0,
        "currency": event.get("currency") or intent.get("currency") or "SGD",
        "provider_ref": provider_ref,
        "provider_payload_shape": event.get("provider_payload_shape") or "generic_provider_event",
        "provider_adapter_warnings": list(event.get("provider_adapter_warnings") or []),
        "source_family": "psp_webhook",
        "adapter_evidence_only": True,
        "payment_execution_performed": False,
        "provider_truth_used": False,
        "raw_provider_payload_stored": False,
    }
    recorded = record_provider_event(str(intent.get("intent_id") or ""), provider_payload, request_meta)
    return {**recorded, "matched": recorded.get("ok") is True, "verified_transport": True}


def create_stripe_sandbox_payment_intent(intent_id: str, workspace_id: str, request_meta: Dict[str, str] | None = None) -> Dict[str, Any]:
    intent = store.get_intent(_clean_id(intent_id, 96), workspace_id)
    if not intent:
        return error("payment_intent_not_found", 404)
    metadata = _as_dict(intent.get("metadata"))
    if intent.get("provider") != "stripe" or metadata.get("validation_environment") != "sandbox":
        return error("stripe_sandbox_intent_requires_stripe_sandbox_validation", 409)
    if str(intent.get("provider_ref") or ""):
        return error("stripe_sandbox_provider_reference_already_bound", 409)
    created = stripe_sandbox.create_payment_intent({
        **intent,
        "financial_leg": metadata.get("financial_leg"),
        "validation_override_id": metadata.get("validation_override_id"),
    })
    if created.get("ok") is False:
        return created
    updated = store.upsert_intent({**intent, "provider_ref": created["provider_ref"], "checkout_hint": "stripe_sandbox_payment_intent", "status": "pending"})
    _append_event(event_type="stripe.sandbox_payment_intent_created", workspace_id=workspace_id, bill_id=updated.get("bill_id", ""), intent_id=updated.get("intent_id", ""), provider="stripe", status="pending", amount=int(updated.get("amount") or 0), currency=updated.get("currency", "SGD"), payload={"provider_ref": created["provider_ref"]}, request_meta=request_meta)
    return _envelope(workspace_id, "stripe_sandbox_payment_intent_created", intent=_intent_safe(updated), checkout_client_secret=created.get("client_secret", ""))


def create_igema_stripe_sandbox_account(payload: Dict[str, Any], request_meta: Dict[str, str] | None = None) -> Dict[str, Any]:
    workspace_id = _clean_id(payload.get("workspace_id") or DEFAULT_WORKSPACE_ID, 96) or DEFAULT_WORKSPACE_ID
    operator_id = _clean_id(payload.get("operator_id"), 96)
    operator_name = _clean_string(payload.get("operator_name"), 120)
    if not operator_id or operator_name.lower() != "igema" or str(payload.get("environment") or "sandbox") != "sandbox":
        return error("igema_sandbox_operator_identity_required", 422)
    existing = store.get_provider_account_for_operator_name(workspace_id, "stripe", "IGEMA", "sandbox")
    if existing:
        return _envelope(
            workspace_id,
            "igema_stripe_sandbox_account_already_exists",
            provider_account=existing,
            created=False,
        )
    created = stripe_sandbox.create_express_account({"operator_id": operator_id})
    if created.get("ok") is False:
        return created
    account = store.upsert_provider_account({"provider_account_id": "provider_account_" + uuid.uuid4().hex[:16], "workspace_id": workspace_id, "provider": "stripe", "operator_id": operator_id, "operator_name": "IGEMA", "environment": "sandbox", "provider_ref": created["provider_ref"], "status": created["status"], "metadata": {"account_type": "express", "founder_test_mode": True}})
    return _envelope(workspace_id, "igema_stripe_sandbox_account_created", provider_account=account, created=True)


