def reconcile_validation_record(validation_id: str, payload: Dict[str, Any], request_meta: Dict[str, str] | None = None) -> Dict[str, Any]:
    """Finance approval completes validation and disables the override automatically."""
    if not isinstance(payload, dict):
        return error("invalid_payload")
    workspace_id = _workspace_id(payload)
    validation_id = _clean_id(validation_id, 96)
    record = store.get_validation_record(validation_id, workspace_id)
    if not record:
        return error("validation_record_not_found", 404)
    if record.get("status") != "provider_event_received":
        return error("validation_provider_event_not_successful", 409, status=record.get("status"))
    bill = store.get_bill(record.get("bill_id", ""), workspace_id)
    intent = store.get_intent(record.get("intent_id", ""), workspace_id)
    override = store.get_validation_override(record.get("override_id", ""), workspace_id)
    if not bill or not intent or not override:
        return error("validation_linkage_incomplete", 409)
    if bill.get("status") not in {"paid", "reconciled", "settled"} or intent.get("status") != "succeeded":
        return error("validation_payment_not_confirmed", 409)
    finance_approved_by = _clean_id(payload.get("finance_approved_by"), 96)
    settlement_reference = _clean_string(payload.get("settlement_reference"), 160)
    if not finance_approved_by or not settlement_reference:
        return error("finance_approval_and_settlement_reference_required")
    now = _now()
    record = store.upsert_validation_record(
        {
            **record,
            "status": "passed",
            "reconciled_at": now,
            "finance_approved_at": now,
            "metadata": {**_as_dict(record.get("metadata")), "finance_approved_by": finance_approved_by, "settlement_reference": settlement_reference, "all_links_reconciled": True},
        }
    )
    override = store.upsert_validation_override(
        {
            **override,
            "status": "passed",
            "metadata": {**_as_dict(override.get("metadata")), "validation_record_id": validation_id, "auto_reverted_to_price_book": True},
        }
    )
    event_id = _append_event(
        event_type="payment.validation_reconciled", workspace_id=workspace_id, bill_id=bill.get("bill_id", ""),
        intent_id=intent.get("intent_id", ""), provider=record.get("provider", ""), status="passed", amount=int(bill.get("amount") or 0),
        currency=bill.get("currency", "SGD"), payload={"validation_id": validation_id, "override_id": override.get("override_id", ""), "normal_price_restored_automatically": True}, request_meta=request_meta,
    )
    return _envelope(workspace_id, "validation_reconciled", event_id=event_id, validation_record=record, validation_override=override, normal_price_restored_automatically=True)


