def _active_refund_amount(
    *,
    workspace_id: str,
    bill_id: str,
    exclude_refund_id: str = "",
) -> int:
    refunds = store.list_refunds(workspace_id=workspace_id, bill_id=bill_id, limit=200)
    return sum(
        int(item.get("amount") or 0)
        for item in refunds
        if item.get("refund_id") != exclude_refund_id and str(item.get("status") or "") in REFUND_ACTIVE_STATUSES
    )


def _completed_refund_amount(
    *,
    workspace_id: str,
    bill_id: str,
    include_refund: Dict[str, Any] | None = None,
) -> int:
    refunds = store.list_refunds(workspace_id=workspace_id, bill_id=bill_id, limit=200)
    completed = sum(
        int(item.get("amount") or 0)
        for item in refunds
        if str(item.get("status") or "") == "completed"
    )
    refund = include_refund or {}
    if refund and str(refund.get("status") or "") == "completed" and not any(
        item.get("refund_id") == refund.get("refund_id") and str(item.get("status") or "") == "completed"
        for item in refunds
    ):
        completed += int(refund.get("amount") or 0)
    return completed


