def record_payment_risk(payload: Dict[str, Any], request_meta: Dict[str, str] | None = None) -> Dict[str, Any]:
    if not isinstance(payload, dict):
        return error("invalid_payload")
    data = {**_as_dict(payload.get("risk") or payload.get("data")), **payload}
    workspace_id = _workspace_id(data)
    case_id = _clean_id(data.get("case_id"), 96)
    if not case_id:
        return error("case_id_required")
    case_response = case_svc.get_case(case_id, workspace_id)
    if case_response.get("ok") is False:
        return case_response
    case_record = _as_dict(case_response.get("case"))
    case_family = _as_dict(case_record.get("family"))
    signal_type = _clean_slug(data.get("signal_type"), "benign", ALLOWED_RISK_SIGNAL_TYPES)
    fixture_registry_key = _clean_string(data.get("fixture_registry_key"), 160)
    if not _g40_policy_effective(signal_type, fixture_registry_key):
        return error("payment_risk_policy_not_effective", 409, signal_type=signal_type)
    risk_id = _clean_id(data.get("risk_id"), 96) or ("risk_" + uuid.uuid4().hex[:16])
    bill_id = _clean_id(data.get("bill_id"), 96)
    refund_id = _clean_id(data.get("refund_id"), 96)
    intent_id = _clean_id(data.get("intent_id"), 96)
    actor_id = _clean_id(data.get("target_actor_id") or data.get("actor_id"), 96)
    payer_id = _clean_id(data.get("payer_id"), 96)
    bill = store.get_bill(bill_id, workspace_id) if bill_id else {}
    refund = store.get_refund(refund_id, workspace_id) if refund_id else {}
    if bill and _clean_id(bill.get("case_id"), 96) != case_id:
        return error("payment_risk_bill_case_mismatch", 403)
    if refund and _clean_id(refund.get("case_id"), 96) != case_id:
        return error("payment_risk_refund_case_mismatch", 403)
    previous_status_group = _clean_slug(case_record.get("status_group") or case_family.get("statusGroup"), "deposit_pending", max_length=80)
    status = "clear" if signal_type == "benign" else "blocked_review"
    blocked_action = _clean_slug(data.get("blocked_action") or "refund_transition", "refund_transition", max_length=80)
    credential_effect: Dict[str, Any] = {"state": "none", "revoked_session_count": 0, "revoked_api_key": False}
    if status == "blocked_review" and actor_id:
        revoked_sessions = identity_session.revoke_active_workspace_sessions(
            workspace_id,
            actor_ids=[actor_id],
            reason="g40_finance_risk_" + signal_type,
            request_meta=request_meta,
        )
        credential_effect["revoked_session_count"] = int(revoked_sessions.get("revoked_count") or 0) if revoked_sessions.get("ok") is not False else 0
        credential_effect["state"] = "revoked"
    key_id = _clean_id(data.get("key_id"), 120)
    if status == "blocked_review" and key_id:
        revoked_key = identity_session.revoke_api_key(
            {"workspace_id": workspace_id, "key_id": key_id, "reason": "g40_finance_risk_" + signal_type},
            request_meta,
        )
        credential_effect["revoked_api_key"] = revoked_key.get("ok") is not False
        credential_effect["state"] = "revoked"
    case_effect = _g40_case_response(
        risk_id=risk_id,
        case_id=case_id,
        workspace_id=workspace_id,
        signal_type=signal_type,
        previous_status_group=previous_status_group,
        request_meta=request_meta,
    )
    ledger_effect = {
        "state": "none" if signal_type == "benign" else "hold_applied",
        "reversal_required": signal_type in {"chargeback", "mistaken_payer"},
        "affected_bill_id": bill_id,
        "affected_refund_id": refund_id,
        "canonical_owner": "LiveUIN TrustPay/LiveLedger",
    }
    summary = {
        "signal_type": signal_type,
        "status": status,
        "blocked_action": blocked_action,
        "policy_state": "effective_test_fixture" if fixture_registry_key else "not_required",
        "fixture_registry_key": fixture_registry_key,
        "reason": _clean_string(data.get("reason") or data.get("risk_reason") or signal_type, 180),
        "credential_effect": credential_effect,
        "ledger_effect": ledger_effect,
        "case_response": case_effect,
        "review_required": status == "blocked_review",
        "review_outcome": "",
    }
    risk = store.upsert_risk(
        {
            "risk_id": risk_id,
            "workspace_id": workspace_id,
            "case_id": case_id,
            "bill_id": bill_id,
            "refund_id": refund_id,
            "intent_id": intent_id,
            "booking_id": _clean_id(data.get("booking_id") or refund.get("booking_id") or bill.get("booking_id"), 96),
            "actor_id": actor_id,
            "payer_id": payer_id or _clean_id(bill.get("payer_id"), 96),
            "signal_type": signal_type,
            "status": status,
            "safe_summary": summary,
            "evidence": {
                **_as_dict(_redact(data.get("evidence") or {})),
                "source_document_ref": _clean_string(data.get("source_document_ref"), 160),
                "provider_reference": _clean_string(data.get("provider_reference"), 160),
                "recorded_at": _now_iso(),
                "canonical_owner": "LiveUIN Finance Risk/Identity/Case",
            },
            "metadata": {
                **_as_dict(_redact(data.get("metadata") or {})),
                "target_actor_role": _clean_slug(data.get("target_actor_role"), "", max_length=80),
                "target_scopes": _as_list(data.get("target_scopes")),
                "previous_status_group": previous_status_group,
                "blocked_action": blocked_action,
            },
            "created_at": _now(),
            "updated_at": _now(),
        }
    )
    event_id = _append_event(
        event_type="risk.signal_recorded",
        workspace_id=workspace_id,
        bill_id=bill_id,
        intent_id=intent_id,
        case_id=case_id,
        booking_id=_clean_id(risk.get("booking_id"), 96),
        status=status,
        amount=int(bill.get("amount") or 0),
        currency=str(bill.get("currency") or "SGD"),
        payload={"risk_id": risk_id, "signal_type": signal_type, "blocked_action": blocked_action},
        request_meta=request_meta,
    )
    return _envelope(workspace_id, "payment_risk_recorded", event_id=event_id, risk=_risk_safe(risk))


def review_payment_risk(
    risk_id: str,
    payload: Dict[str, Any],
    request_meta: Dict[str, str] | None = None,
) -> Dict[str, Any]:
    if not isinstance(payload, dict):
        return error("invalid_payload")
    data = {**_as_dict(payload.get("review") or payload.get("data")), **payload}
    workspace_id = _workspace_id(data)
    risk_id = _clean_id(risk_id or data.get("risk_id"), 96)
    if not risk_id:
        return error("risk_id_required")
    risk = store.get_risk(risk_id, workspace_id)
    if not risk:
        return error("payment_risk_not_found", 404)
    decision = _clean_slug(data.get("decision"), "", max_length=80)
    if decision not in {"clear", "reverse"}:
        return error("payment_risk_review_decision_required", 400)
    summary = _as_dict(risk.get("safe_summary"))
    metadata = _as_dict(risk.get("metadata"))
    previous_status_group = _clean_slug(metadata.get("previous_status_group"), "deposit_pending", max_length=80)
    ticket_id = _clean_id(_as_dict(summary.get("case_response")).get("ticket_id"), 96)
    credential_response: Dict[str, Any] = {}
    restored_api_key: Dict[str, Any] = {}
    actor_id = _clean_id(risk.get("actor_id"), 96)
    actor_role = _clean_slug(data.get("restore_actor_role") or metadata.get("target_actor_role"), "finance_manager", max_length=80)
    target_scopes = [str(item) for item in _as_list(data.get("restore_scopes") or metadata.get("target_scopes")) if str(item).strip()]
    if actor_id and _bool(data.get("restore_session"), True):
        credential_response = identity_session.issue_session(
            {
                "workspace_id": workspace_id,
                "actor_id": actor_id,
                "role": actor_role,
                "scopes": target_scopes or ["payment.refund.review", "payment.status.read"],
                "ttl_seconds": 3600,
                "auth_method": "g40_risk_review_restore",
                "metadata": {"risk_id": risk_id, "review_decision": decision},
            },
            request_meta,
        )
    if actor_id and _bool(data.get("restore_api_key"), True):
        restored_api_key = identity_session.issue_api_key(
            {
                "workspace_id": workspace_id,
                "actor_id": actor_id,
                "role": actor_role,
                "scopes": target_scopes or ["payment.status.read"],
                "ttl_seconds": 86400,
                "key_id": _clean_id(data.get("new_key_id"), 120) or ("risk_reissue_" + uuid.uuid4().hex[:12]),
                "metadata": {"risk_id": risk_id, "review_decision": decision},
            },
            request_meta,
        )
    _g40_restore_case_response(
        case_id=risk.get("case_id", ""),
        workspace_id=workspace_id,
        previous_status_group=previous_status_group,
        request_meta=request_meta,
        ticket_id=ticket_id,
    )
    updated = store.upsert_risk(
        {
            **risk,
            "status": "reversed" if decision == "reverse" else "restored",
            "safe_summary": {
                **summary,
                "review_required": False,
                "review_outcome": decision,
                "reviewed_at": _now_iso(),
                "credential_effect": {
                    **_as_dict(summary.get("credential_effect")),
                    "state": "restored",
                    "restored_session": credential_response.get("ok") is not False if credential_response else False,
                    "restored_api_key": restored_api_key.get("ok") is not False if restored_api_key else False,
                },
                "ledger_effect": {
                    **_as_dict(summary.get("ledger_effect")),
                    "state": "reversed" if decision == "reverse" else "released",
                },
                "case_response": {
                    **_as_dict(summary.get("case_response")),
                    "state": "resolved",
                    "ticket_id": ticket_id,
                },
            },
            "metadata": {
                **metadata,
                "review_decision": decision,
                "reviewed_by_actor_id": _clean_id((request_meta or {}).get("access_actor_id"), 96),
            },
            "updated_at": _now(),
        }
    )
    event_id = _append_event(
        event_type="risk.reviewed",
        workspace_id=workspace_id,
        bill_id=risk.get("bill_id", ""),
        intent_id=risk.get("intent_id", ""),
        case_id=risk.get("case_id", ""),
        booking_id=risk.get("booking_id", ""),
        status=updated.get("status", ""),
        payload={"risk_id": risk_id, "decision": decision},
        request_meta=request_meta,
    )
    return _envelope(
        workspace_id,
        "payment_risk_reviewed",
        event_id=event_id,
        risk=_risk_safe(updated),
        restored_session=credential_response.get("one_time_credential", {}),
        restored_api_key=restored_api_key.get("one_time_credential", {}),
    )


def case_payment_risk(case_id: str, workspace_id: str = DEFAULT_WORKSPACE_ID, limit: int = 50) -> Dict[str, Any]:
    workspace_id = _clean_id(workspace_id, 96) or DEFAULT_WORKSPACE_ID
    guard = _require_case(case_id, workspace_id)
    if guard.get("ok") is False:
        return guard
    risks = store.list_risks(workspace_id=workspace_id, case_id=guard["case_id"], limit=limit)
    return _envelope(
        workspace_id,
        "payment_risk_case_loaded",
        case_id=guard["case_id"],
        risks=[_risk_safe(item) for item in risks],
        risk_count=len(risks),
    )


def _refund_escalation_ticket(
    *,
    refund: Dict[str, Any],
    bill: Dict[str, Any],
    summary: Dict[str, Any],
    request_meta: Dict[str, str] | None,
    reason_code: str,
) -> Dict[str, Any]:
    existing = _as_dict(summary.get("escalation"))
    if not reason_code:
        ticket_id = _clean_id(existing.get("ticket_id"), 96)
        if ticket_id:
            try:
                ops_ticket_svc.transition_ticket(
                    ticket_id,
                    {
                        "workspace_id": refund.get("workspace_id") or bill.get("workspace_id") or DEFAULT_WORKSPACE_ID,
                        "status": "resolved",
                        "public_summary": "Refund lifecycle recovered after reviewed settlement path.",
                        "resolution": "Refund lifecycle recovered and canonical ledger state reconciled.",
                    },
                    request_meta,
                )
            except Exception:
                pass
            return {
                **existing,
                "state": "recovered",
                "reason_code": "",
                "resolved_at": _now_iso(),
            }
        return {"state": "not_required", "reason_code": "", "ticket_id": "", "canonical_owner": "LiveUIN Ops"}

    workspace_id = _clean_id(refund.get("workspace_id") or bill.get("workspace_id"), 96) or DEFAULT_WORKSPACE_ID
    ticket_payload = {
        "workspace_id": workspace_id,
        "case_id": refund.get("case_id") or bill.get("case_id") or "",
        "booking_id": refund.get("booking_id") or bill.get("booking_id") or "",
        "room_id": _bill_context(bill).get("room_id", ""),
        "category": "payment",
        "priority": "high" if reason_code in {"provider_failed", "refund_disputed"} else "normal",
        "severity": "s2" if reason_code in {"provider_failed", "refund_disputed"} else "s3",
        "status": "escalated",
        "owner_label": "LiveUIN Finance Ops",
        "public_summary": _clean_string(summary.get("summary") or "Refund lifecycle escalated.", 240),
        "internal_note": _clean_string(
            "Refund "
            + str(refund.get("refund_id") or "")
            + " requires finance/Ops review for "
            + reason_code
            + ".",
            500,
        ),
        "metadata": {
            "refund_id": refund.get("refund_id", ""),
            "bill_id": bill.get("bill_id", ""),
            "intent_id": refund.get("intent_id", ""),
            "reason_code": reason_code,
            "surface": "refund_lifecycle_g39",
        },
    }
    ticket_id = _clean_id(existing.get("ticket_id"), 96)
    if ticket_id:
        try:
            ops_ticket_svc.transition_ticket(
                ticket_id,
                {
                    "workspace_id": workspace_id,
                    "status": "escalated",
                    "public_summary": ticket_payload["public_summary"],
                    "metadata": ticket_payload["metadata"],
                },
                request_meta,
            )
        except Exception:
            pass
    return {
        **existing,
        "state": "escalated",
            "reason_code": reason_code,
            "ticket_id": ticket_id,
            "ticket_status": "escalated",
            "updated_at": _now_iso(),
            "canonical_owner": "LiveUIN Ops",
        }
    created = ops_ticket_svc.create_ticket(ticket_payload, request_meta, transport="payment_refund_g39")
    ticket = _as_dict(created.get("ticket"))
    return {
        "state": "escalated" if created.get("ok") is not False else "escalation_record_failed",
        "reason_code": reason_code,
        "ticket_id": _clean_id(ticket.get("ticket_id") or created.get("ticket_id"), 96),
        "ticket_status": _clean_slug(ticket.get("status"), "escalated", max_length=80),
        "created_at": _now_iso(),
        "canonical_owner": "LiveUIN Ops",
    }


