def request_refund(payload: Dict[str, Any], request_meta: Dict[str, str] | None = None) -> Dict[str, Any]:
    if not isinstance(payload, dict):
        return error("invalid_payload")
    data = {**_as_dict(payload.get("refund") or payload.get("data")), **payload}
    workspace_id = _workspace_id(data)
    bill_id = _clean_id(data.get("bill_id"), 96)
    if not bill_id:
        return error("bill_id_required")
    bill = store.get_bill(bill_id, workspace_id)
    if not bill:
        return error("bill_not_found", 404)
    case_id = _clean_id(data.get("case_id") or bill.get("case_id"), 96)
    if case_id and case_id != bill.get("case_id", ""):
        return error("refund_bill_case_mismatch", 403)
    bill_status = _clean_slug(bill.get("status"), "unpaid", ALLOWED_BILL_STATUS)
    if bill_status not in {"paid", "overpaid", "partially_refunded", "reconciled", "settled"}:
        return error("refund_bill_not_refundable", 409, bill_status=bill_status)

    amount = _bounded_int(data.get("amount"), int(bill.get("amount") or 0))
    if amount <= 0:
        return error("refund_amount_required")
    available = max(0, int(bill.get("amount") or 0) - _active_refund_amount(workspace_id=workspace_id, bill_id=bill_id))
    if amount > available:
        return error("refund_amount_exceeds_available", 409, available_amount=available)

    intent_id = _clean_id(data.get("intent_id"), 96)
    intents = store.list_intents_for_bill(bill_id, workspace_id, limit=20)
    if intent_id:
        intent = store.get_intent(intent_id, workspace_id)
        if not intent or intent.get("bill_id") != bill_id:
            return error("refund_intent_bill_mismatch", 403)
    else:
        intent = next(
            (
                item
                for item in intents
                if str(item.get("status") or "") in {"succeeded", "partially_refunded", "refunded"}
            ),
            intents[0] if intents else {},
        )
        intent_id = _clean_id(intent.get("intent_id"), 96)

    refund_id = _clean_id(data.get("refund_id"), 96) or "refund_" + uuid.uuid4().hex[:16]
    status = "requested"
    reason = _clean_string(data.get("reason") or data.get("reason_code") or "operator_refund_review", 180)
    currency = _clean_string(data.get("currency") or bill.get("currency") or "SGD", 12).upper()
    summary = _refund_summary_payload(
        refund_id=refund_id,
        bill=bill,
        refund={},
        amount=amount,
        currency=currency,
        status=status,
        reason=reason,
        data={**data, "intent_id": intent_id},
        request_meta=request_meta,
        available_before=available,
        completed_before=_completed_refund_amount(workspace_id=workspace_id, bill_id=bill_id),
        completed_after=_completed_refund_amount(workspace_id=workspace_id, bill_id=bill_id),
    )
    refund = store.upsert_refund(
        {
            "refund_id": refund_id,
            "workspace_id": workspace_id,
            "case_id": bill.get("case_id", ""),
            "bill_id": bill_id,
            "intent_id": intent_id,
            "booking_id": bill.get("booking_id", ""),
            "amount": amount,
            "currency": currency,
            "status": status,
            "reason": reason,
            "safe_summary": summary,
            "evidence": _refund_evidence(data, status),
            "metadata": {
                **_as_dict(_redact(data.get("metadata") or {})),
                "canonical_owner": "LiveUIN TrustPay/LiveLedger",
                "provider_role": "processor_adapter_or_manual_evidence_only",
                "payment_provider_truth_used": False,
                "ledger_reversal_required": True,
                "source": _refund_source(data),
                **_premium_finance_metadata(
                    data,
                    _as_dict(bill.get("metadata")),
                    bill_currency=currency,
                    payment_received_at=_clean_string(_as_dict(bill.get("receipt")).get("paid_at"), 40),
                ),
            },
            "created_at": _now(),
            "updated_at": _now(),
        }
    )
    event_id = _append_event(
        event_type="refund.requested",
        workspace_id=workspace_id,
        bill_id=bill_id,
        intent_id=intent_id,
        case_id=bill.get("case_id", ""),
        booking_id=bill.get("booking_id", ""),
        status=status,
        amount=amount,
        currency=currency,
        payload={"refund_id": refund_id, "reason": reason, "available_amount": available},
        request_meta=request_meta,
    )
    _append_case_payment_event(
        case_id=bill.get("case_id", ""),
        workspace_id=workspace_id,
        event_type="refund.requested",
        label="Refund requested",
        detail="LiveUIN TrustPay recorded a refund request for finance review.",
        state="review",
        status_group="refund_review",
        request_meta=request_meta,
    )
    return _envelope(workspace_id, "refund_requested", event_id=event_id, refund=_refund_safe(refund), bill=_bill_safe(bill))


def transition_refund(
    refund_id: str,
    payload: Dict[str, Any],
    request_meta: Dict[str, str] | None = None,
) -> Dict[str, Any]:
    if not isinstance(payload, dict):
        return error("invalid_payload")
    data = {**_as_dict(payload.get("refund") or payload.get("data")), **payload}
    workspace_id = _workspace_id(data)
    refund_id = _clean_id(refund_id or data.get("refund_id"), 96)
    if not refund_id:
        return error("refund_id_required")
    refund = store.get_refund(refund_id, workspace_id)
    if not refund:
        return error("refund_not_found", 404)
    current_status = _clean_slug(refund.get("status"), "requested", ALLOWED_REFUND_STATUS)
    target_status = _refund_target_status(data)
    if target_status not in ALLOWED_REFUND_STATUS:
        return error("refund_status_not_supported", target_status=target_status)
    if current_status != target_status and target_status not in REFUND_TRANSITIONS.get(current_status, set()):
        return error("refund_transition_not_supported", 409, current_status=current_status, target_status=target_status)

    bill = store.get_bill(refund.get("bill_id", ""), workspace_id)
    if not bill:
        return error("bill_not_found", 404)
    active_risk = _g40_blocking_risk(
        workspace_id=workspace_id,
        case_id=str(refund.get("case_id") or bill.get("case_id") or ""),
        bill_id=str(refund.get("bill_id") or ""),
        refund_id=refund_id,
        actor_id=_clean_id((request_meta or {}).get("access_actor_id"), 96),
    )
    if active_risk and target_status in {"approved", "initiated", "completed"}:
        return error(
            "payment_risk_review_required",
            409,
            risk_id=active_risk.get("risk_id", ""),
            signal_type=active_risk.get("signal_type", ""),
            blocked_action="refund_transition",
        )
    intent = store.get_intent(refund.get("intent_id", ""), workspace_id) if refund.get("intent_id") else {}
    reason = _clean_string(data.get("reason") or refund.get("reason") or "operator_refund_review", 180)
    completed_before = _completed_refund_amount(workspace_id=workspace_id, bill_id=bill.get("bill_id", ""))
    completed_after = completed_before
    if target_status == "completed" and current_status != "completed":
        completed_after = completed_before + int(refund.get("amount") or 0)
    elif target_status != "completed" and current_status == "completed":
        completed_after = max(0, completed_before - int(refund.get("amount") or 0))
    summary = _refund_summary_payload(
        refund_id=refund_id,
        bill=bill,
        refund=refund,
        amount=int(refund.get("amount") or 0),
        currency=str(refund.get("currency") or bill.get("currency") or "SGD"),
        status=target_status,
        reason=reason,
        data={**data, "intent_id": refund.get("intent_id", "")},
        request_meta=request_meta,
        available_before=max(0, int(bill.get("amount") or 0) - _active_refund_amount(workspace_id=workspace_id, bill_id=bill.get("bill_id", ""), exclude_refund_id=refund_id)),
        completed_before=completed_before,
        completed_after=completed_after,
    )
    delayed = bool(_as_dict(summary.get("settlement")).get("provider_delay_visible"))
    escalation_reason = ""
    if delayed:
        escalation_reason = "provider_delay"
    elif target_status == "failed":
        escalation_reason = "provider_failed"
    elif target_status == "disputed":
        escalation_reason = "refund_disputed"
    elif target_status in {"completed", "cancelled"}:
        escalation_reason = ""
    summary["escalation"] = _refund_escalation_ticket(
        refund=refund,
        bill=bill,
        summary=summary,
        request_meta=request_meta,
        reason_code=escalation_reason,
    )
    evidence = {
        **_as_dict(refund.get("evidence")),
        **_refund_evidence(data, target_status, payment_execution_performed=False),
    }
    updated_refund = store.upsert_refund(
        {
            **refund,
            "status": target_status,
            "reason": reason,
            "safe_summary": summary,
            "evidence": evidence,
            "metadata": {
                **_as_dict(refund.get("metadata")),
                **_as_dict(_redact(data.get("metadata") or {})),
                "last_transition": target_status,
                "provider_role": "processor_adapter_or_manual_evidence_only",
                "payment_provider_truth_used": False,
                "ledger_reversal_required": target_status == "completed",
                "source": _refund_source(data, refund),
                **_premium_finance_metadata(
                    data,
                    _as_dict(refund.get("metadata")) or _as_dict(bill.get("metadata")),
                    bill_currency=str(refund.get("currency") or bill.get("currency") or "SGD"),
                    payment_received_at=_clean_string(_as_dict(bill.get("receipt")).get("paid_at"), 40),
                ),
            },
            "updated_at": _now(),
        }
    )

    updated_bill = bill
    updated_intent = intent
    if target_status == "completed":
        completed_amount = completed_after
        bill_amount = int(bill.get("amount") or 0)
        new_status = "refunded" if completed_amount >= bill_amount else "partially_refunded"
        refund_receipt = {
            "refund_id": refund_id,
            "amount": int(refund.get("amount") or 0),
            "currency": str(refund.get("currency") or bill.get("currency") or "SGD"),
            "refunded_at": _clean_string(_as_dict(summary.get("settlement")).get("actual_settlement_at"), 40) or _now_iso(),
            "status": new_status,
            "ledger_reversal_status": summary.get("ledger_reversal_status", "pending_liveledger_reversal"),
            "source": "liveuin_trustpay",
            "canonical": True,
        }
        updated_bill = store.upsert_bill(
            {
                **bill,
                "status": new_status,
                "receipt": {**_as_dict(bill.get("receipt")), "latest_refund": refund_receipt},
                "metadata": {
                    **_as_dict(bill.get("metadata")),
                    "last_refund_id": refund_id,
                    "refund_status": new_status,
                    "ledger_reversal_status": summary.get("ledger_reversal_status", "pending_liveledger_reversal"),
                    "provider_truth_used": False,
                    **_premium_finance_metadata(
                        data,
                        _as_dict(bill.get("metadata")),
                        bill_currency=str(refund.get("currency") or bill.get("currency") or "SGD"),
                        payment_received_at=_clean_string(_as_dict(bill.get("receipt")).get("paid_at"), 40),
                    ),
                },
                "updated_at": _now(),
            }
        )
        if intent:
            updated_intent = store.upsert_intent(
                {
                    **intent,
                    "status": new_status,
                    "receipt": {**_as_dict(intent.get("receipt")), "latest_refund": refund_receipt},
                    "metadata": {
                        **_as_dict(intent.get("metadata")),
                        "last_refund_id": refund_id,
                        "refund_status": new_status,
                        "provider_role": "processor_adapter_only",
                    },
                    "updated_at": _now(),
                }
            )
        _append_case_payment_event(
            case_id=bill.get("case_id", ""),
            workspace_id=workspace_id,
            event_type="refund.completed",
            label="Refund completed",
            detail="LiveUIN TrustPay completed the refund, recorded settlement, and captured the parent-safe communication state.",
            state="complete" if summary.get("ledger_reversal_status") == "recorded" else "review",
            status_group="refund_completed",
            request_meta=request_meta,
        )
    elif target_status == "failed":
        _append_case_payment_event(
            case_id=bill.get("case_id", ""),
            workspace_id=workspace_id,
            event_type="refund.failed",
            label="Refund execution failed",
            detail="LiveUIN kept the refund visible, escalated it to Ops, and did not treat the request as settled.",
            state="warning",
            status_group="refund_escalated",
            request_meta=request_meta,
        )
    elif target_status == "disputed":
        _append_case_payment_event(
            case_id=bill.get("case_id", ""),
            workspace_id=workspace_id,
            event_type="refund.disputed",
            label="Refund disputed",
            detail="Refund dispute recorded; settlement remains under reviewed finance and Ops handling.",
            state="warning",
            status_group="refund_escalated",
            request_meta=request_meta,
        )
    elif target_status == "initiated" and delayed:
        _append_case_payment_event(
            case_id=bill.get("case_id", ""),
            workspace_id=workspace_id,
            event_type="refund.delayed",
            label="Refund delayed",
            detail="Provider settlement is overdue, so the refund stays visible and escalated until recovery completes.",
            state="warning",
            status_group="refund_delay",
            request_meta=request_meta,
        )
    elif target_status == "cancelled":
        _append_case_payment_event(
            case_id=bill.get("case_id", ""),
            workspace_id=workspace_id,
            event_type="refund.cancelled",
            label="Refund cancelled",
            detail="Refund request cancelled without claiming settlement.",
            state="complete",
            status_group="refund_cancelled",
            request_meta=request_meta,
        )

    event_id = _append_event(
        event_type="refund.transitioned",
        workspace_id=workspace_id,
        bill_id=bill.get("bill_id", ""),
        intent_id=refund.get("intent_id", ""),
        case_id=bill.get("case_id", ""),
        booking_id=bill.get("booking_id", ""),
        status=target_status,
        amount=int(refund.get("amount") or 0),
        currency=str(refund.get("currency") or bill.get("currency") or "SGD"),
        payload={"refund_id": refund_id, "previous_status": current_status, "target_status": target_status},
        request_meta=request_meta,
    )
    return _envelope(
        workspace_id,
        "refund_transitioned",
        event_id=event_id,
        refund=_refund_safe(updated_refund),
        bill=_bill_safe(updated_bill),
        intent=_intent_safe(updated_intent) if updated_intent else {},
    )


def case_payment_status(case_id: str, workspace_id: str = DEFAULT_WORKSPACE_ID, limit: int = 50) -> Dict[str, Any]:
    workspace_id = _clean_id(workspace_id, 96) or DEFAULT_WORKSPACE_ID
    guard = _require_case(case_id, workspace_id)
    if guard.get("ok") is False:
        return guard
    case_id = guard["case_id"]
    bills = store.list_bills_for_case(case_id, workspace_id, limit)
    intents = store.list_intents_for_case(case_id, workspace_id, limit)
    exceptions = store.list_exceptions(workspace_id=workspace_id, status="", case_id=case_id, limit=limit)
    refunds = store.list_refunds(workspace_id=workspace_id, case_id=case_id, limit=limit)
    payers = store.list_payers_for_case(case_id, workspace_id, limit)
    booking_payments = [_booking_payment_safe(item) for item in booking_svc.pass_booking_payments_for_case(case_id, workspace_id)]
    pass_payments = [_pass_payment_safe(item) for item in pass_store.list_for_case("pass_payment_records", case_id, workspace_id, limit=limit)]
    canonical_bill_payments = [_canonical_payment_from_bill(item) for item in bills]
    normalized_payments = canonical_bill_payments + booking_payments + pass_payments
    safe_exceptions = [_exception_safe(item) for item in exceptions]
    safe_refunds = [_refund_safe(item) for item in refunds]
    runtime = _runtime_overview(case_id, workspace_id, "holder")
    return _envelope(
        workspace_id,
        "case_payment_status_loaded",
        case_id=case_id,
        runtime=runtime,
        payers=[_payer_safe(item) for item in payers],
        bills=[_bill_safe(item) for item in bills],
        intents=[_intent_safe(item) for item in intents],
        exceptions=safe_exceptions,
        refunds=safe_refunds,
        normalized_payments=normalized_payments,
        booking_deposit_payments=booking_payments,
        pass_transport_payments=pass_payments,
        summary=_payment_summary(normalized_payments, safe_exceptions, safe_refunds),
    )


def property_payment_status(
    property_id: str,
    workspace_id: str = DEFAULT_WORKSPACE_ID,
    limit: int = 50,
    viewer_role: str = "operator",
    case_id: str = "",
) -> Dict[str, Any]:
    workspace_id = _clean_id(workspace_id, 96) or DEFAULT_WORKSPACE_ID
    property_id = _clean_id(property_id, 96)
    if not property_id:
        return error("property_id_required")
    visibility = finance_visibility_policy(viewer_role, case_id)
    scoped_case_id = _clean_id(case_id, 96)
    if visibility.get("requires_case_scope") and not scoped_case_id:
        return error("viewer_case_scope_required", 403, visibility_policy=visibility)
    bills = [item for item in store.list_bills(workspace_id=workspace_id, status="", limit=max(200, _bounded_int(limit, 50))) if _bill_matches_property(item, property_id)]
    if scoped_case_id:
        bills = [item for item in bills if _clean_id(item.get("case_id"), 96) == scoped_case_id]
    if visibility.get("commercial_only"):
        bills = [item for item in bills if _clean_slug(item.get("purpose_type"), "other") in COMMERCIAL_PURPOSE_TYPES]
    bills = bills[: max(1, min(200, int(limit or 50)))]
    bill_ids = {item.get("bill_id", "") for item in bills if item.get("bill_id")}
    case_ids = {item.get("case_id", "") for item in bills if item.get("case_id")}
    intents = [
        item
        for item in store.list_intents_for_case(scoped_case_id, workspace_id, limit=max(200, _bounded_int(limit, 50)))
    ] if scoped_case_id else []
    if not intents:
        intents = []
        for candidate_case_id in sorted(case_ids):
            intents.extend(store.list_intents_for_case(candidate_case_id, workspace_id, limit=max(50, _bounded_int(limit, 50))))
    intents = [item for item in intents if item.get("bill_id") in bill_ids]
    exceptions = store.list_exceptions(workspace_id=workspace_id, status="", case_id=scoped_case_id, limit=max(200, _bounded_int(limit, 50))) if scoped_case_id else store.list_exceptions(workspace_id=workspace_id, status="", limit=max(200, _bounded_int(limit, 50)))
    exceptions = [
        item
        for item in exceptions
        if item.get("bill_id") in bill_ids or (item.get("case_id") in case_ids and not item.get("bill_id"))
    ]
    refunds = store.list_refunds(workspace_id=workspace_id, status="", case_id=scoped_case_id, limit=max(200, _bounded_int(limit, 50))) if scoped_case_id else store.list_refunds(workspace_id=workspace_id, status="", limit=max(200, _bounded_int(limit, 50)))
    refunds = [item for item in refunds if item.get("bill_id") in bill_ids or item.get("case_id") in case_ids]
    payers = []
    for candidate_case_id in sorted(case_ids):
        payers.extend(store.list_payers_for_case(candidate_case_id, workspace_id, limit=max(20, _bounded_int(limit, 50))))
    canonical_bill_payments = [_canonical_payment_from_bill(item) for item in bills]
    documents = _documents_for_property(property_id, bills, refunds, visibility)
    property_summary = _property_finance_summary(
        property_id=property_id,
        bills=bills,
        exceptions=exceptions,
        refunds=refunds,
        documents=documents,
    )
    return _envelope(
        workspace_id,
        "property_payment_status_loaded",
        property_id=property_id,
        case_id=scoped_case_id,
        visibility_policy=visibility,
        property_summary=property_summary,
        payers=[_payer_safe(item) for item in payers[: max(1, min(200, int(limit or 50)))]],
        bills=[_bill_safe(item) for item in bills],
        intents=[_intent_safe(item) for item in intents[: max(1, min(200, int(limit or 50)))]],
        exceptions=[_exception_safe(item) for item in exceptions[: max(1, min(200, int(limit or 50)))]],
        refunds=[_refund_safe(item) for item in refunds[: max(1, min(200, int(limit or 50)))]],
        normalized_payments=canonical_bill_payments,
        documents=documents,
        receipts=[item for item in documents if item.get("document_type") == "receipt"],
        summary=property_summary.get("summary", {}),
    )


