"""Minimal server-only Stripe sandbox adapter for canonical TrustPay intents."""

import base64
import json
import os
from pathlib import Path
from typing import Any, Dict
from urllib.parse import urlencode
from urllib.request import Request, urlopen


API_BASE = "https://api.stripe.com/v1"
CREDENTIAL_NAME = "STRIPE_SECRET_KEY"


def _secret() -> str:
    directory = str(os.getenv("CREDENTIALS_DIRECTORY") or "").strip()
    if not directory:
        return ""
    path = (Path(directory).resolve() / CREDENTIAL_NAME).resolve()
    try:
        path.relative_to(Path(directory).resolve())
    except ValueError:
        return ""
    if not path.is_file() or path.stat().st_size > 65536:
        return ""
    value = path.read_text(encoding="utf-8").strip()
    return value if value.startswith("sk_test_") else ""


def status() -> Dict[str, Any]:
    return {
        "ok": True,
        "provider": "stripe",
        "environment": "sandbox",
        "credential_ready": bool(_secret()),
        "credential_name": CREDENTIAL_NAME,
        "provider_role": "payment_intent_adapter_only",
        "raw_secret_exposed": False,
    }


def create_payment_intent(intent: Dict[str, Any]) -> Dict[str, Any]:
    secret = _secret()
    if not secret:
        return {"ok": False, "detail": "stripe_sandbox_secret_key_required", "status_code": 503}
    amount = int(intent.get("amount") or 0)
    currency = str(intent.get("currency") or "SGD").lower()
    if amount <= 0 or len(currency) != 3:
        return {"ok": False, "detail": "stripe_sandbox_amount_or_currency_invalid", "status_code": 422}
    metadata = {
        "liveuin_intent_id": str(intent.get("intent_id") or ""),
        "liveuin_bill_id": str(intent.get("bill_id") or ""),
        "liveuin_workspace_id": str(intent.get("workspace_id") or ""),
        "liveuin_environment": "sandbox",
        "liveuin_financial_leg": str(intent.get("financial_leg") or ""),
        "liveuin_validation_override_id": str(intent.get("validation_override_id") or ""),
    }
    payload: Dict[str, str] = {
        "amount": str(amount),
        "currency": currency,
        "payment_method_types[]": "card",
    }
    payload.update({"metadata[" + key + "]": value for key, value in metadata.items() if value})
    request = Request(
        API_BASE + "/payment_intents",
        data=urlencode(payload).encode("utf-8"),
        method="POST",
        headers={"Authorization": "Basic " + base64.b64encode((secret + ":").encode()).decode(), "Content-Type": "application/x-www-form-urlencoded"},
    )
    try:
        with urlopen(request, timeout=20) as response:  # nosec B310: fixed Stripe API base.
            data = json.loads(response.read().decode("utf-8"))
    except Exception as exc:
        return {"ok": False, "detail": "stripe_sandbox_request_failed", "status_code": 502, "error_type": exc.__class__.__name__}
    provider_ref = str(data.get("id") or "")
    if not provider_ref.startswith("pi_"):
        return {"ok": False, "detail": "stripe_sandbox_payment_intent_reference_missing", "status_code": 502}
    return {"ok": True, "provider_ref": provider_ref, "client_secret": str(data.get("client_secret") or ""), "status": str(data.get("status") or "requires_payment_method")}


def create_express_account(operator: Dict[str, Any]) -> Dict[str, Any]:
    secret = _secret()
    if not secret:
        return {"ok": False, "detail": "stripe_sandbox_secret_key_required", "status_code": 503}
    payload = {"type": "express", "country": "SG", "capabilities[transfers][requested]": "true", "metadata[liveuin_operator_id]": str(operator.get("operator_id") or ""), "metadata[liveuin_environment]": "sandbox"}
    request = Request(API_BASE + "/accounts", data=urlencode(payload).encode("utf-8"), method="POST", headers={"Authorization": "Basic " + base64.b64encode((secret + ":").encode()).decode(), "Content-Type": "application/x-www-form-urlencoded"})
    try:
        with urlopen(request, timeout=20) as response:  # nosec B310: fixed Stripe API base.
            data = json.loads(response.read().decode("utf-8"))
    except Exception as exc:
        return {"ok": False, "detail": "stripe_sandbox_account_request_failed", "status_code": 502, "error_type": exc.__class__.__name__}
    reference = str(data.get("id") or "")
    return {"ok": reference.startswith("acct_"), "provider_ref": reference, "status": "created" if reference else ""}

