CONFIG = Path('/etc/liveuin-marketing-publication/owner-instruction.json')
ASSETS = Path(__file__).resolve().parent
COOKIE = '__Host-LiveUIN-Rental'
HOST_ORIGIN = 'https://host.liveuin.com'
PUBLIC_ORIGINS = {'https://www.liveuin.com', 'https://liveuin.com'}
PUBLIC_HOME = 'https://www.liveuin.com'
PAGE_HEADERS = {**PRIVATE_HEADERS, 'X-Frame-Options': 'DENY', 'Content-Security-Policy':
                "default-src 'none'; script-src 'self'; style-src 'self'; img-src 'self'; connect-src 'self'; frame-ancestors 'none'; base-uri 'none'; form-action 'self'"}


def load_instruction():
    try:
        fd = os.open(CONFIG, os.O_RDONLY | os.O_NOFOLLOW)
        with os.fdopen(fd, encoding='utf-8') as handle:
            info = os.fstat(handle.fileno())
            require(stat.S_ISREG(info.st_mode) and info.st_uid == 0 and not info.st_mode & 0o022
                    and info.st_size <= 32768, 'publication_instruction_permissions_invalid', 503)
            data = json.load(handle)
    except (OSError, ValueError):
        raise WorkflowError('publication_instruction_unavailable', 503) from None
    require(data.get('schema_version') == 'liveuin-owner-marketing-instruction-v1'
            and data.get('enabled') is True, 'publication_instruction_inactive', 503)
    require(datetime.fromisoformat(data['review_due_at'].replace('Z', '+00:00')).timestamp() > time.time(),
            'publication_instruction_review_due', 503)
    return data


class SourceEvidence:
    def __init__(self, instruction_loader, capture_reader, capture_fingerprint, media_root):
        self.loader, self.reader, self.capture_hash = instruction_loader, capture_reader, capture_fingerprint
        self.media_root = Path(media_root).resolve()

    def capture(self, workspace, submission):
        config = self.loader()
        require(workspace == config['workspace_id'] and submission == config['submission_id'],
                'publication_instruction_scope_denied', 403)
        capture = self.reader(submission, workspace)
        metadata = capture.get('metadata') or {}
        review = metadata.get('operator_review') or {}
        require(metadata.get('partner_actor_id') == config['owner_actor_id']
                and self.capture_hash(capture) == config['source_sha256'], 'publication_source_changed')
        require(review.get('decision') == 'accepted_for_marketing'
                and review.get('review_case_id') == config['media_review_id']
                and review.get('audit_event_id') == config['media_review_audit_id']
                and review.get('content_sha256') == config['source_sha256'], 'publication_review_changed')
        selected = set((metadata.get('listing_draft') or {}).get('selected_video_frame_ids') or [])
        require(set(config['public_media_ids']) <= selected, 'publication_media_selection_changed')
        return config, capture

    def __call__(self, workspace, submission):
        config, _ = self.capture(workspace, submission)
        return {'approval_id': config['instruction_id'], 'authority_evidence_id': config['authority_evidence_id'],
                'media_review_id': config['media_review_id'], 'approved_by': config['owner_actor_id'],
                'owner_actor_id': config['owner_actor_id'], 'source_sha256': config['source_sha256'],
                'workspace_id': workspace, 'submission_id': submission, 'purpose': 'marketing_publication',
                'state': 'approved', 'source_current': True, 'authority_current': True,
                'public_terms_sha256': fingerprint(validate_terms(config['terms'])),
                'public_media_ids': config['public_media_ids'],
                'expires_at': int(datetime.fromisoformat(config['review_due_at'].replace('Z', '+00:00')).timestamp())}

    def image(self, workspace, submission, media_id):
        config, capture = self.capture(workspace, submission)
        require(media_id in config['public_media_ids'], 'public_media_not_found', 404)
        row = next((r for r in (capture.get('metadata') or {}).get('partner_video_frame_candidates', [])
                    if r.get('candidate_id') == media_id), {})
        uri = urlparse(row.get('storage_uri', ''))
        require(uri.scheme == 'file' and not uri.netloc and row.get('media_type') == 'image/jpeg', 'public_media_not_found', 404)
        path = Path(unquote(uri.path)).resolve()
        expected_root = self.media_root / 'partner-upload-quarantine' / workspace / submission / 'derived-video-frames'
        require(path.is_relative_to(expected_root) and path.is_file() and path.stat().st_size <= 12000000,
                'public_media_not_found', 404)
        require('sha256:' + hashlib.sha256(path.read_bytes()).hexdigest() == row.get('checksum'),
                'public_media_integrity_changed', 503)
        return path


def owner_capability(actor, config):
    # A listing-scoped capability, not a new global role/scope in Identity.
    require(actor.get('verified_session') is True and actor.get('role') in {'owner', 'host'}
            and actor.get('actor_id') == config['owner_actor_id']
            and actor.get('workspace_id') == config['workspace_id']
            and 'inventory.media.submit' in actor.get('scopes', []), 'publication_owner_scope_denied', 403)
    return {**actor, 'scopes': [*actor['scopes'], 'inventory.marketing.publish']}


def application_policy(config, payload):
    rule = config.get('country_policy') or {}
    require(rule.get('country_code') == 'SG' and rule.get('property_class') == 'private_residential'
            and rule.get('application_floor_months') == 3 and rule.get('application_only') is True,
            'country_application_policy_unavailable', 503)
    months = payload.get('lease_months')
    require(type(months) is int and months >= rule['application_floor_months'],
            'SG_private_residential_minimum_three_consecutive_months', 422)
    # This is only an application floor. Occupancy/title/licensing/tenancy checks
    # are deliberately not represented as approved by this public marketing path.


def build_production_router():
    # Called by the running Core app, with its existing configured store bindings.
    from . import core_inventory_store as inventory_store
    from . import core_demand_store as demand_store
    from . import core_media_capture_store as capture_store
    from . import core_media_solo_review_service as reviewed_source
    from . import core_identity_session as identity
    from . import core_identity_login as login
    from . import core_identity_api as identity_api

    evidence = SourceEvidence(load_instruction, capture_store.get_capture, reviewed_source.content_fingerprint,
                              capture_store.data_dir())
    marketing = MarketingWorkflow(inventory_store.sqlite_path(), evidence)
    offers = RentalOfferWorkflow(demand_store.sqlite_path(), marketing)
    signed = session_dependency(identity.resolve_access_context)
    router = APIRouter()

    def origin(request, permitted):
        expected = 'https://' + request.headers.get('host', '').split(':')[0].lower()
        require(expected in permitted and request.headers.get('origin') == expected, 'same_origin_required', 403)

    def translate(call):
        try:
            return call()
        except WorkflowError as exc:
            raise HTTPException(exc.status, exc.detail, headers=PRIVATE_HEADERS) from None

    def owner(request: Request):
        return translate(lambda: owner_capability(signed(request), load_instruction()))

    def applicant(request: Request):
        # Separate host-only HttpOnly rental session; never overwrite Host/Ops sign-in.
        raw = request.cookies.get(COOKIE, '')
        if not raw or len(raw) > 12000:
            raise HTTPException(401, 'rental_sign_in_required', headers=PRIVATE_HEADERS)
        try:
            saved = json.loads(base64.urlsafe_b64decode(raw))
            headers = saved['headers']
            require(isinstance(headers, dict) and set(headers) <= {
                'X-LiveUIN-Workspace-Id', 'X-LiveUIN-Actor-Id', 'X-LiveUIN-Role', 'X-LiveUIN-Scopes',
                'X-LiveUIN-Session-Id', 'X-LiveUIN-Session-Issued-At', 'X-LiveUIN-Auth-Method',
                'X-LiveUIN-Session-Signature'}, 'rental_sign_in_required', 401)
            scope = dict(request.scope)
            scope['headers'] = [(k.lower().encode(), str(v).encode()) for k, v in headers.items()]
            actor = signed(Request(scope))
            require(actor['role'] == 'tenant' and 'living.application.write' in actor['scopes'], 'rental_applicant_required', 403)
            return actor
        except (ValueError, KeyError, TypeError, WorkflowError):
            raise HTTPException(401, 'rental_sign_in_required', headers=PRIVATE_HEADERS) from None

    def reader(request: Request):
        return owner(request) if request.headers.get('host') == 'host.liveuin.com' else applicant(request)

    class CheckedOffers:
        def submit(self, actor, listing_id, payload):
            application_policy(load_instruction(), payload)
            email = str(payload.get('contact_email') or '').strip().lower()
            expected = 'identity:' + hashlib.sha256(hashlib.sha256(email.encode()).hexdigest().encode()).hexdigest()[:16]
            require(hmac.compare_digest(actor['actor_id'], expected), 'contact_email_must_match_verified_sign_in', 422)
            return offers.submit(actor, listing_id, {**payload, 'contact_email': email})

        def __getattr__(self, name):
            return getattr(offers, name)

    router.include_router(build_router(marketing, CheckedOffers(), owner, applicant, reader,
                                       allowed_origins={HOST_ORIGIN, *PUBLIC_ORIGINS}))

    @router.get('/api/core/inventory/marketing-owner')
    def owner_status(actor: dict = Depends(owner)):
        def get():
            config = load_instruction()
            evidence(config['workspace_id'], config['submission_id'])
            with marketing.connection() as c:
                row = c.execute('SELECT listing_id,state FROM inventory_marketing_publications WHERE workspace_id=? AND submission_id=?',
                                (actor['workspace_id'], config['submission_id'])).fetchone()
            return {'terms': config['terms'], 'submission_id': config['submission_id'],
                    'public_media_ids': config['public_media_ids'], 'instruction_id': config['instruction_id'],
                    'public_url': PUBLIC_HOME + '/stays/' + row['listing_id'] if row else None,
                    'listing_id': row['listing_id'] if row else None, 'state': row['state'] if row else 'ready_to_publish',
                    'independently_verified': False, 'payment_enabled': False}
        return JSONResponse(translate(get), headers=PRIVATE_HEADERS)

    @router.get('/stays/{listing_id}', include_in_schema=False)
    def public_page(listing_id: str):
        translate(lambda: marketing.get_public(listing_id))
        return FileResponse(ASSETS / 'marketing_listing.html', headers=PAGE_HEADERS)

    @router.get('/host/listing-publication', include_in_schema=False)
    def owner_page():
        return FileResponse(ASSETS / 'marketing_owner.html', headers=PAGE_HEADERS)

    @router.get('/__liveuin_marketing__/app.js', include_in_schema=False)
    def script():
        return FileResponse(ASSETS / 'marketing_publication.js', media_type='application/javascript', headers=PRIVATE_HEADERS)

    @router.get('/__liveuin_marketing__/style.css', include_in_schema=False)
    def stylesheet():
        return FileResponse(ASSETS / 'marketing_publication.css', media_type='text/css', headers=PRIVATE_HEADERS)

    @router.get('/api/core/inventory/marketing-publications/{listing_id}/media/{media_id}', include_in_schema=False)
    def public_image(listing_id: str, media_id: str):
        def get():
            listing = marketing.get_public(listing_id)
            require(media_id in listing['public_media_ids'], 'public_media_not_found', 404)
            private = marketing.record(listing_id)
            return evidence.image(private['workspace_id'], private['submission_id'], media_id)
        return FileResponse(translate(get), media_type='image/jpeg', headers=PRIVATE_HEADERS)

    @router.post('/api/core/demand/rental-auth/request')
    def request_code(request: Request, payload: dict = Body(...)):
        def run():
            origin(request, PUBLIC_ORIGINS)
            require(set(payload) == {'email', 'listing_id'}, 'auth_fields_invalid', 422)
            marketing.get_public(payload['listing_id'])
            email = str(payload['email']).strip().lower()
            require(len(email) <= 254 and identity_api._looks_like_email(email), 'valid_email_required', 422)
            digest = hashlib.sha256(email.encode()).hexdigest()
            workspace = 'rental_' + digest[:24]
            # Persisted rate limits across restarts using the canonical challenge store.
            recent = login.store.list_challenges(workspace_id=workspace, limit=20)
            now = int(time.time())
            require(not any(int(r.get('issued_at') or 0) > now - 60 for r in recent)
                    and sum(int(r.get('issued_at') or 0) > now - 3600 for r in recent) < 5,
                    'please_wait_before_requesting_another_code', 429)
            result = login.create_login_challenge({'workspace_id': workspace, 'channel': 'email',
                'purpose': 'member_app', 'surface': 'rental_application', 'target_hash': digest,
                'role': 'tenant', 'scopes': ['living.application.write'], 'ttl_seconds': 600,
                'metadata': {'marketing_listing_id': payload['listing_id'], 'raw_email_stored': False}},
                identity_api._request_meta(request))
            require(result.get('ok') is True, 'email_sign_in_unavailable', 503)
            once = result['one_time_challenge']
            delivery = identity_api._otp_gateway_deliver(email, once['challenge_id'], once['verification_code'])
            if delivery.get('ok') is not True:
                login.cancel_login_challenge(once['challenge_id'], {'workspace_id': workspace})
                raise WorkflowError('email_code_delivery_unavailable', 503)
            return {'ok': True, 'challenge_id': once['challenge_id'], 'delivery_status': 'sent'}
        return JSONResponse(translate(run), headers=PRIVATE_HEADERS)

    @router.post('/api/core/demand/rental-auth/verify')
    def verify_code(request: Request, payload: dict = Body(...)):
        def run():
            origin(request, PUBLIC_ORIGINS)
            require(set(payload) == {'challenge_id', 'code', 'listing_id'}, 'auth_fields_invalid', 422)
            challenge = login.store.get_challenge(str(payload['challenge_id']))
            metadata = challenge.get('metadata') or {}
            require(metadata.get('surface') == 'rental_application'
                    and metadata.get('marketing_listing_id') == payload['listing_id'], 'rental_challenge_scope_denied', 403)
            marketing.get_public(payload['listing_id'])
            result = login.verify_login_challenge(payload['challenge_id'],
                {'workspace_id': challenge['workspace_id'], 'code': str(payload['code']), 'session_ttl_seconds': 3600},
                identity_api._request_meta(request), trusted_role='tenant', trusted_scopes=['living.application.write'])
            require(result.get('ok') is True, 'code_invalid_expired_or_already_used', 403)
            credential = result['one_time_credential']
            headers = dict(credential['session_headers'])
            headers['X-LiveUIN-Session-Id'] = credential['session_id']
            response = JSONResponse({'ok': True, 'authenticated': True}, headers=PRIVATE_HEADERS)
            cookie = base64.urlsafe_b64encode(json.dumps({'headers': headers}).encode()).decode()
            response.set_cookie(COOKIE, cookie, max_age=3600, httponly=True, secure=True, samesite='strict', path='/')
            return response
        return translate(run)

    @router.get('/api/core/demand/rental-auth/session')
    def auth_status(actor: dict = Depends(applicant)):
        return JSONResponse({'ok': True, 'authenticated': True, 'role': actor['role']}, headers=PRIVATE_HEADERS)

    @router.get('/api/core/demand/rental-self')
    def own_application(listing_id: str, actor: dict = Depends(applicant)):
        # Works after the ad is paused; applicants retain access to their receipt.
        lead_id = 'leadpass_' + fingerprint({'listing': listing_id, 'actor': actor['actor_id']})[:24]
        return JSONResponse(translate(lambda: offers.get_offer(actor, lead_id)), headers=PRIVATE_HEADERS)

    return router

