def _request_meta(request: Request) -> Dict[str, str]:
    return {
        "ip": request.client.host if request.client else "",
        "user_agent": str(request.headers.get("user-agent") or "")[:500],
        "referer": str(request.headers.get("referer") or "")[:500],
    }


def _raise_if_error(response: Dict[str, Any]) -> Dict[str, Any]:
    if response.get("ok") is not False:
        return response

    raise HTTPException(
        status_code=int(response.get("status_code") or 400),
        detail=str(response.get("detail") or "core_booking_error"),
    )


def _bind_session_participant(payload: Dict[str, Any], meta: Dict[str, str]) -> Dict[str, Any]:
    actor_id = str(meta.get("access_actor_id") or "")
    if not actor_id:
        return {"ok": False, "detail": "participant_grant_required", "status_code": 403}
    for field in ("participant_id", "person_id"):
        supplied = str((payload if isinstance(payload, dict) else {}).get(field) or "")
        if supplied and supplied != actor_id:
            return {"ok": False, "detail": "participant_grant_required", "status_code": 403}
    return {
        **(payload if isinstance(payload, dict) else {}),
        "participant_id": actor_id,
        "person_id": actor_id,
        "canonical_identity_resolved": True,
    }


def _create_booking_bound_to_session(payload: Dict[str, Any], meta: Dict[str, str], *, transport: str = "core_api") -> Dict[str, Any]:
    bound_payload = _bind_session_participant(payload, meta)
    if bound_payload.get("ok") is False:
        return bound_payload
    return svc.create_booking(bound_payload, meta, transport=transport)


