def _now() -> int:
    return int(time.time())


def _now_iso() -> str:
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())


def _iso_from_epoch(value: Any) -> str:
    try:
        epoch = int(value)
    except (TypeError, ValueError):
        epoch = 0
    if epoch <= 0:
        return ""
    return time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime(epoch))


def _clean_string(value: Any, max_length: int = 240) -> str:
    return str(value or "").strip()[:max_length]


def _clean_id(value: Any, max_length: int = 96) -> str:
    cleaned = re.sub(r"[^A-Za-z0-9_.:-]", "", str(value or "").strip())
    return cleaned[:max_length]


def _clean_slug(value: Any, default: str, allowed: set[str] | None = None, max_length: int = 80) -> str:
    cleaned = re.sub(r"[^a-z0-9_]", "_", str(value or "").strip().lower())
    cleaned = re.sub(r"_+", "_", cleaned).strip("_")
    cleaned = (cleaned or default)[:max_length]
    if allowed and cleaned not in allowed:
        return default
    return cleaned


def _as_dict(value: Any) -> Dict[str, Any]:
    return value if isinstance(value, dict) else {}


def _bounded_int(value: Any, default: int, low: int = 0, high: int = 100000000) -> int:
    try:
        number = int(value)
    except (TypeError, ValueError):
        number = default
    return max(low, min(high, number))


def _workspace_id(payload: Dict[str, Any], fallback: str = DEFAULT_WORKSPACE_ID) -> str:
    return _clean_id(payload.get("workspace_id") or fallback, 96) or DEFAULT_WORKSPACE_ID


def error(detail: str, status_code: int = 400, **extra: Any) -> Dict[str, Any]:
    return {"ok": False, "detail": detail, "status_code": status_code, **extra}


def _case_exists(case_id: str, workspace_id: str) -> bool:
    response = case_svc.get_case(case_id, workspace_id)
    return response.get("ok") is not False


def _require_case(case_id: str, workspace_id: str) -> Dict[str, Any]:
    case_id = _clean_id(case_id, 96)
    workspace_id = _clean_id(workspace_id, 96) or DEFAULT_WORKSPACE_ID
    if not case_id:
        return error("case_id_required")
    if not _case_exists(case_id, workspace_id):
        return error("case_not_found", 404)
    return {"ok": True, "case_id": case_id, "workspace_id": workspace_id}


def _hold_record(hold_id: str, workspace_id: str) -> Dict[str, Any]:
    hold_id = _clean_id(hold_id, 120)
    if not hold_id:
        return {}
    with inventory_store.connection() as conn:
        row = conn.execute(
            """
            SELECT *
            FROM inventory_holds
            WHERE workspace_id = ?
              AND hold_id = ?
            LIMIT 1;
            """,
            (workspace_id, hold_id),
        ).fetchone()
    return inventory_store.row_to_hold(row)


def _require_hold(hold_id: str, workspace_id: str, case_id: str, room_id: str) -> Dict[str, Any]:
    hold_id = _clean_id(hold_id, 120)
    if not hold_id:
        return error("hold_id_required")
    hold = _hold_record(hold_id, workspace_id)
    if not hold:
        return error("inventory_hold_not_found", 404)
    if _clean_id(hold.get("case_id"), 96) != case_id:
        return error("booking_hold_case_mismatch", 403)
    if room_id and _clean_id(hold.get("unit_id"), 96) != room_id:
        return error("booking_hold_room_mismatch", 403)
    if hold.get("status") != "active":
        return error("booking_hold_not_active", 409, hold_status=hold.get("status", ""))
    if int(hold.get("expires_at") or 0) <= _now():
        return error("booking_hold_expired", 409)

    offer = inventory_store.get_offer(hold.get("unit_id", ""), workspace_id)
    if not offer:
        return error("inventory_offer_not_found", 404)
    return {"ok": True, "hold": hold, "offer": offer, "room_id": hold.get("unit_id", "")}


def _require_viewing(viewing_id: str, workspace_id: str, case_id: str, room_id: str) -> Dict[str, Any]:
    viewing_id = _clean_id(viewing_id, 96)
    if not viewing_id:
        return {"ok": True, "viewing": {}}
    viewing_response = viewing_svc.get_reservation(viewing_id, workspace_id)
    if viewing_response.get("ok") is False:
        return viewing_response
    viewing = _as_dict(viewing_response.get("viewing") or viewing_response.get("reservation"))
    if _clean_id(viewing.get("case_id"), 96) != case_id:
        return error("booking_viewing_case_mismatch", 403)
    if room_id and _clean_id(viewing.get("room_id"), 96) != room_id:
        return error("booking_viewing_room_mismatch", 403)
    if viewing.get("status") in {"cancelled", "expired", "no_show", "waitlisted"}:
        return error("booking_viewing_not_ready", 409, viewing_status=viewing.get("status", ""))
    return {"ok": True, "viewing": viewing}


def _append_event(
    *,
    event_type: str,
    workspace_id: str,
    case_id: str,
    booking_id: str,
    hold_id: str = "",
    viewing_id: str = "",
    room_id: str = "",
    payload: Dict[str, Any] | None = None,
    request_meta: Dict[str, str] | None = None,
) -> str:
    event_id = "book_evt_" + uuid.uuid4().hex[:16]
    store.append_event(
        {
            "event_id": event_id,
            "workspace_id": workspace_id,
            "case_id": case_id,
            "booking_id": booking_id,
            "hold_id": hold_id,
            "viewing_id": viewing_id,
            "room_id": room_id,
            "event_type": event_type,
            "payload": {
                **(payload or {}),
                "source": "liveuin_booking",
                "canonical_owner": "LiveUIN Booking/TrustPay",
            },
            "received_at": _now(),
        },
        request_meta,
    )
    return event_id


def _append_case_timeline(
    *,
    case_id: str,
    workspace_id: str,
    event_type: str,
    label: str,
    detail: str,
    state: str,
    status_group: str = "",
    request_meta: Dict[str, str] | None,
) -> None:
    payload: Dict[str, Any] = {
        "workspace_id": workspace_id,
        "event_type": event_type,
        "timeline_item": {
