        request_meta,
        workspace_id=workspace_id,
        route_surface="core",
    )


def _offer_version_binding_payload(
    offer_version_id: Any,
    offer_version_hash: Any,
    *,
    decision_surface: str,
    bound_at: str = "",
) -> Dict[str, Any]:
    return {
        "binding_type": "exact_offer_version_v1",
        "offer_version_id": _clean_string(offer_version_id, 160),
        "offer_version_hash": _clean_string(offer_version_hash, 160),
        "decision_surface": _clean_string(decision_surface, 80),
        "bound_at": _clean_string(bound_at or _now_iso(), 40),
    }


def _current_offer_version_binding(room_id: str, workspace_id: str) -> Dict[str, Any]:
    room_id = _clean_id(room_id, 96)
    workspace_id = _clean_id(workspace_id, 96) or DEFAULT_WORKSPACE_ID
    offer = inventory_store.get_offer(room_id, workspace_id)
    if not offer:
        return error("inventory_offer_not_found", 404)
    freshness = inventory_svc._offer_freshness_projection(offer)
    raw_binding = inventory_svc._g32_offer_version_binding(offer)
    binding = _offer_version_binding_payload(
        raw_binding.get("offer_version_id", ""),
        raw_binding.get("offer_version_hash", ""),
        decision_surface="inventory_offer_current",
        bound_at=_clean_string(raw_binding.get("bound_at") or freshness.get("cache_invalidated_at"), 40),
    )
    return {"ok": True, "offer": offer, "freshness": freshness, "binding": binding}


def _binding_from_hold(hold: Dict[str, Any], room_id: str, workspace_id: str) -> Dict[str, Any]:
    metadata = _as_dict(hold.get("metadata"))
    binding = _as_dict(metadata.get("offer_version_binding"))
    if binding.get("offer_version_id") and binding.get("offer_version_hash"):
        return {
            "ok": True,
            "binding": _offer_version_binding_payload(
                binding.get("offer_version_id", ""),
                binding.get("offer_version_hash", ""),
                decision_surface=_clean_string(binding.get("decision_surface") or "inventory_hold", 80),
                bound_at=_clean_string(binding.get("bound_at"), 40),
            ),
        }
    return _current_offer_version_binding(room_id, workspace_id)


def g32_offer_version_gate_for_booking_record(record: Dict[str, Any], workspace_id: str | None = None) -> Dict[str, Any]:
    booking = _as_dict(record)
    booking_workspace_id = _clean_id(workspace_id or booking.get("workspace_id"), 96) or DEFAULT_WORKSPACE_ID
    room_id = _clean_id(booking.get("room_id"), 96)
    metadata = _as_dict(booking.get("metadata"))
    approved_binding = _as_dict(metadata.get("offer_version_binding"))
    if not approved_binding:
        approved_binding = _as_dict(booking.get("offer_version_binding"))
    if not approved_binding:
        approved_binding = _as_dict(_as_dict(booking.get("booking")).get("offer_version_binding"))
    if not room_id:
        return error("booking_offer_room_required", 409, booking_id=booking.get("booking_id", ""))
    if not approved_binding.get("offer_version_id") or not approved_binding.get("offer_version_hash"):
        return error("booking_offer_version_binding_required", 409, booking_id=booking.get("booking_id", ""))
    current = _current_offer_version_binding(room_id, booking_workspace_id)
    if current.get("ok") is False:
        return current
    freshness = _as_dict(current.get("freshness"))
    current_binding = _as_dict(current.get("binding"))
    if freshness.get("freshness_state") != "current":
        return error(
            "booking_offer_version_no_longer_current",
            409,
            booking_id=booking.get("booking_id", ""),
            approved_offer_version_id=approved_binding.get("offer_version_id", ""),
            approved_offer_version_hash=approved_binding.get("offer_version_hash", ""),
            current_offer_version_id=current_binding.get("offer_version_id", ""),
            current_offer_version_hash=current_binding.get("offer_version_hash", ""),
            freshness_state=freshness.get("freshness_state", ""),
            missing_fields=freshness.get("missing_fields", []),
        )
    if (
        approved_binding.get("offer_version_id") != current_binding.get("offer_version_id")
        or approved_binding.get("offer_version_hash") != current_binding.get("offer_version_hash")
    ):
        return error(
            "booking_offer_version_changed_requires_renewed_decision",
            409,
            booking_id=booking.get("booking_id", ""),
            approved_offer_version_id=approved_binding.get("offer_version_id", ""),
            approved_offer_version_hash=approved_binding.get("offer_version_hash", ""),
            current_offer_version_id=current_binding.get("offer_version_id", ""),
            current_offer_version_hash=current_binding.get("offer_version_hash", ""),
        )
    return {
        "ok": True,
        "booking": booking,
        "offer": current.get("offer", {}),
        "freshness": freshness,
        "offer_version_binding": current_binding,
    }


def g32_offer_version_gate_for_booking(booking_id: str, workspace_id: str = DEFAULT_WORKSPACE_ID) -> Dict[str, Any]:
    booking_id = _clean_id(booking_id, 96)
    workspace_id = _clean_id(workspace_id, 96) or DEFAULT_WORKSPACE_ID
    if not booking_id:
        return error("booking_id_required")
    booking = store.get_booking(booking_id, workspace_id)
    if not booking:
        return error("booking_not_found", 404)
    return g32_offer_version_gate_for_booking_record(booking, workspace_id)


def _booking_safe(record: Dict[str, Any]) -> Dict[str, Any]:
    if not record:
        return {}

    booking = dict(_as_dict(record.get("booking")))
    booking.setdefault("booking_id", record.get("booking_id", ""))
    booking.setdefault("room_id", record.get("room_id", ""))
    booking.setdefault("hold_id", record.get("hold_id", ""))
    booking.setdefault("viewing_id", record.get("viewing_id", ""))
    booking.setdefault("status", record.get("status", "draft"))
    booking.setdefault("deposit_status", record.get("deposit_status", "not_required"))
    metadata = _as_dict(record.get("metadata"))
    return {
        "booking_id": record.get("booking_id", ""),
        "id": record.get("booking_id", ""),
        "case_id": record.get("case_id", ""),
        "caseId": record.get("case_id", ""),
        "person_id": record.get("person_id", ""),
        "room_id": record.get("room_id", ""),
        "roomId": record.get("room_id", ""),
        "hold_id": record.get("hold_id", ""),
        "viewing_id": record.get("viewing_id", ""),
        "status": record.get("status", "draft"),
        "deposit_status": record.get("deposit_status", "not_required"),
        "deposit": {
            "amount": int(record.get("deposit_amount") or 0),
            "currency": record.get("currency", "SGD"),
            "status": record.get("deposit_status", "not_required"),
            "provider_ref": record.get("provider_ref", ""),
            "ledger": _as_dict(record.get("ledger")),
            "source": "liveuin_trustpay",
            "canonical": True,
        },
        "booking": booking,
        "offer_version_binding": _as_dict(metadata.get("offer_version_binding")),
        "source": "liveuin_booking",
        "canonical": True,
        "updated_at": _iso_from_epoch(record.get("updated_at")),
    }


def _booking_payment_safe(record: Dict[str, Any]) -> Dict[str, Any]:
    return {
        "payment_id": "booking_deposit_" + record.get("booking_id", ""),
        "booking_id": record.get("booking_id", ""),
        "case_id": record.get("case_id", ""),
        "type": "deposit",
        "payment_type": "deposit",
        "amount": int(record.get("deposit_amount") or 0),
        "currency": record.get("currency", "SGD"),
        "status": record.get("deposit_status", "not_required"),
        "provider_ref": record.get("provider_ref", ""),
        "ledger": _as_dict(record.get("ledger")),
        "source": "liveuin_trustpay",
        "canonical": True,
        "updated_at": _iso_from_epoch(record.get("updated_at")),
    }


def _envelope(
    *,
    status: str,
    workspace_id: str,
    event_id: str = "",
    booking: Dict[str, Any] | None = None,
    inventory: Dict[str, Any] | None = None,
    transport: str = "core_api",
) -> Dict[str, Any]:
    response: Dict[str, Any] = {
        "ok": True,
        "schema_version": SCHEMA_VERSION,
        "phase": PHASE,
        "source": "liveuin_booking",
        "canonical_owner": "LiveUIN Booking/TrustPay",
        "surface": "liveuin_core_booking",
        "layer": "canonical_source_of_truth",
        "transport": transport,
        "workspace_id": workspace_id,
        "status": status,
        "event_id": event_id,
        "routes": {
            "status": "/api/core/booking/status",
            "bookings": "/api/core/booking/bookings",
            "pass_bookings": "/api/pass/{case_id}/bookings",
        },
        "boundary": {
            "surface": "Laijuzhu Pass, Mini Program booking request, LiveUIN app, and ops booking board",
            "layer": "canonical source of truth",
            "owner": "LiveUIN Booking/TrustPay",
            "channel_role": "request/display transport only",
        },
    }
    if booking:
        response["booking_id"] = booking.get("booking_id", "")
        response["case_id"] = booking.get("case_id", "")
        response["room_id"] = booking.get("room_id", "")
        response["hold_id"] = booking.get("hold_id", "")
        response["viewing_id"] = booking.get("viewing_id", "")
        response["booking"] = _booking_safe(booking)
        response["deposit"] = response["booking"]["deposit"]
    if inventory:
        response["inventory"] = inventory
    return response


def create_booking(
    payload: Dict[str, Any],
    request_meta: Dict[str, str] | None = None,
    *,
    transport: str = "core_api",
) -> Dict[str, Any]:
    if not isinstance(payload, dict):
        return error("invalid_payload")

    data = _as_dict(payload.get("booking") or payload.get("data"))
    payload = {**data, **payload}
    workspace_id = _workspace_id(payload)
    guard = _require_case(payload.get("case_id") or payload.get("pass_id"), workspace_id)
    if guard.get("ok") is False:
        return guard
    participant_grant_id = _clean_id(payload.get("participant_grant_id") or payload.get("grant_id"), 140)
    participant_id = _clean_id(payload.get("participant_id") or payload.get("person_id"), 120)
    grant_guard = g11_svc.enforce_consumer_access(
        consumer="booking_actions",
        workspace_id=workspace_id,
        case_id=guard["case_id"],
        grant_id=participant_grant_id,
        participant_id=participant_id,
        identity_resolved=payload.get("canonical_identity_resolved") is True,
        resource_id=_clean_id(payload.get("booking_id") or payload.get("hold_id") or payload.get("reservation_id"), 140) or guard["case_id"],
        request_meta=request_meta,
        stale_cache_decision=_as_dict(payload.get("stale_cache_decision")),
        in_flight_operation=_as_dict(payload.get("in_flight_operation")),
    )
    if grant_guard.get("ok") is False:
        detail = grant_guard.get("detail") or "participant_grant_denied"
        return error("participant_grant_required" if detail == "participant_grant_required" else detail, grant_guard.get("status_code") or 403, g11_enforcement=grant_guard)

    hold_id = _clean_id(payload.get("hold_id"), 120)
    room_id = _clean_id(payload.get("room_id") or payload.get("unit_id"), 96)
    hold_guard = _require_hold(hold_id, workspace_id, guard["case_id"], room_id)
    if hold_guard.get("ok") is False:
        return hold_guard
    room_id = _clean_id(hold_guard.get("room_id") or room_id, 96)

    viewing_id = _clean_id(payload.get("viewing_id") or payload.get("reservation_id"), 96)
    viewing_guard = _require_viewing(viewing_id, workspace_id, guard["case_id"], room_id)
    if viewing_guard.get("ok") is False:
        return viewing_guard
    offer_binding_guard = _binding_from_hold(_as_dict(hold_guard.get("hold")), room_id, workspace_id)
    if offer_binding_guard.get("ok") is False:
        return offer_binding_guard
    offer_binding = _as_dict(offer_binding_guard.get("binding"))

    deposit_amount = _bounded_int(payload.get("deposit_amount") or payload.get("amount"), 0)
    currency = _clean_string(payload.get("currency") or _as_dict(hold_guard.get("offer")).get("currency") or "SGD", 12).upper()
    deposit_status = "pending" if deposit_amount > 0 else "not_required"
    status = "deposit_pending" if deposit_amount > 0 else "hold_ready"
    booking_id = _clean_id(payload.get("booking_id"), 96) or "book_" + uuid.uuid4().hex[:16]
    booking_claim = store.create_booking_atomic(
        {
            "booking_id": booking_id,
            "workspace_id": workspace_id,
            "case_id": guard["case_id"],
            "person_id": _clean_id(payload.get("person_id"), 96),
            "room_id": room_id,
            "hold_id": hold_id,
            "viewing_id": viewing_id,
            "status": status,
            "deposit_status": deposit_status,
            "deposit_amount": deposit_amount,
            "currency": currency,
            "provider_ref": _clean_string(payload.get("provider_ref"), 160),
            "ledger": {
                **_as_dict(payload.get("ledger")),
                "deposit_state": deposit_status,
                "canonical_owner": "LiveUIN TrustPay/LiveLedger",
            },
            "booking": {
                **_as_dict(payload.get("booking")),
                "booking_id": booking_id,
                "room_id": room_id,
                "hold_id": hold_id,
                "viewing_id": viewing_id,
                "status": status,
                "deposit_status": deposit_status,
                "offer_version_binding": offer_binding,
            },
            "metadata": {
                **_as_dict(payload.get("metadata")),
                "canonical_owner": "LiveUIN Booking/TrustPay",
                "surface": _clean_string(payload.get("surface") or "laijuzhu_pass", 80),
                "operator_role": "assigned fulfilment execution only",
                "preferred_operator_brand": "IGEMA when assigned",
                "raw_provider_secret_stored": False,
                "offer_version_binding": offer_binding,
            },
        }
    )
    booking_record = booking_claim.get("booking") if isinstance(booking_claim.get("booking"), dict) else {}
    if booking_claim.get("created") is not True:
        return error("booking_hold_already_used", 409, booking_id=booking_record.get("booking_id", ""))
    event_id = _append_event(
        event_type="booking.deposit_pending" if deposit_amount > 0 else "booking.hold_ready",
        workspace_id=workspace_id,
        case_id=guard["case_id"],
        booking_id=booking_id,
        hold_id=hold_id,
        viewing_id=viewing_id,
        room_id=room_id,
        payload={
            "status": status,
            "deposit_status": deposit_status,
            "deposit_amount": deposit_amount,
            "currency": currency,
        },
        request_meta=request_meta,
    )
    _append_case_timeline(
        case_id=guard["case_id"],
        workspace_id=workspace_id,
        event_type="booking.deposit_pending",
        label="Deposit pending" if deposit_amount > 0 else "Booking hold ready",
        detail="Booking record is ready for deposit." if deposit_amount > 0 else "Booking record is ready without a deposit requirement.",
        state="pending" if deposit_amount > 0 else "complete",
        status_group="deposit_pending" if deposit_amount > 0 else "",
        request_meta=request_meta,
    )
    return _envelope(status="booking_created", workspace_id=workspace_id, event_id=event_id, booking=booking_record, transport=transport)


def get_booking(booking_id: str, workspace_id: str = DEFAULT_WORKSPACE_ID) -> Dict[str, Any]:
    booking_id = _clean_id(booking_id, 96)
    workspace_id = _clean_id(workspace_id, 96) or DEFAULT_WORKSPACE_ID
    if not booking_id:
        return error("booking_id_required")
    booking = store.get_booking(booking_id, workspace_id)
    if not booking:
        return error("booking_not_found", 404)
    return _envelope(status="booking_loaded", workspace_id=workspace_id, booking=booking)


def list_bookings(workspace_id: str = DEFAULT_WORKSPACE_ID, status: str = "", limit: int = 50) -> Dict[str, Any]:
