def create_deposit_intent(
    booking_id: str,
    payload: Dict[str, Any],
    request_meta: Dict[str, str] | None = None,
) -> Dict[str, Any]:
    if not isinstance(payload, dict):
        return error("invalid_payload")
    workspace_id = _workspace_id(payload)
    booking_id = _clean_id(booking_id or payload.get("booking_id"), 96)
    if not booking_id:
        return error("booking_id_required")
    existing = store.get_booking(booking_id, workspace_id)
    if not existing:
        return error("booking_not_found", 404)
    if existing.get("status") in {"confirmed", "cancelled", "expired", "failed"}:
        return error("booking_not_open_for_deposit", 409, booking_status=existing.get("status", ""))
    version_guard = g32_offer_version_gate_for_booking_record(existing, workspace_id)
    if version_guard.get("ok") is False:
        return version_guard

    deposit_amount = _bounded_int(payload.get("deposit_amount") or payload.get("amount"), int(existing.get("deposit_amount") or 0))
    if deposit_amount <= 0:
        return error("deposit_amount_required")
    provider_ref = _clean_string(payload.get("provider_ref") or existing.get("provider_ref"), 160)
    updated = store.upsert_booking(
        {
            **existing,
            "status": "deposit_pending",
            "deposit_status": "intent_created",
            "deposit_amount": deposit_amount,
            "currency": _clean_string(payload.get("currency") or existing.get("currency") or "SGD", 12).upper(),
            "provider_ref": provider_ref,
            "ledger": {
                **_as_dict(existing.get("ledger")),
                **_as_dict(payload.get("ledger")),
                "deposit_state": "intent_created",
                "canonical_owner": "LiveUIN TrustPay/LiveLedger",
            },
            "booking": {
                **_as_dict(existing.get("booking")),
                "status": "deposit_pending",
                "deposit_status": "intent_created",
            },
            "metadata": {
                **_as_dict(existing.get("metadata")),
                **_as_dict(payload.get("metadata")),
                "raw_provider_secret_stored": False,
                "last_deposit_intent_at": _now_iso(),
                "offer_version_binding": _as_dict(version_guard.get("offer_version_binding")),
            },
            "updated_at": _now(),
        }
    )
    event_id = _append_event(
        event_type="payment.intent_created",
        workspace_id=workspace_id,
        case_id=updated.get("case_id", ""),
        booking_id=booking_id,
        hold_id=updated.get("hold_id", ""),
        viewing_id=updated.get("viewing_id", ""),
        room_id=updated.get("room_id", ""),
        payload={"deposit_status": "intent_created", "deposit_amount": deposit_amount, "currency": updated.get("currency", "SGD")},
        request_meta=request_meta,
    )
    _append_case_timeline(
        case_id=updated.get("case_id", ""),
        workspace_id=workspace_id,
        event_type="payment.intent_created",
        label="Payment intent created",
        detail="Deposit intent is ready for family review.",
        state="pending",
        status_group="deposit_pending",
        request_meta=request_meta,
    )
    return _envelope(status="deposit_intent_created", workspace_id=workspace_id, event_id=event_id, booking=updated)


def transition_booking(
    booking_id: str,
    payload: Dict[str, Any],
    request_meta: Dict[str, str] | None = None,
) -> Dict[str, Any]:
    if not isinstance(payload, dict):
        return error("invalid_payload")
    workspace_id = _workspace_id(payload)
    booking_id = _clean_id(booking_id or payload.get("booking_id"), 96)
    if not booking_id:
        return error("booking_id_required")
    existing = store.get_booking(booking_id, workspace_id)
    if not existing:
        return error("booking_not_found", 404)

    target = _clean_slug(payload.get("status") or payload.get("target_status") or payload.get("action"), existing.get("status", "draft"), ALLOWED_BOOKING_STATUS)
    deposit_status = _clean_slug(payload.get("deposit_status") or existing.get("deposit_status"), existing.get("deposit_status") or "not_required", ALLOWED_DEPOSIT_STATUS)
    inventory_response: Dict[str, Any] = {}
    event_type = "booking.updated"
    status_group = ""
    label = "Booking updated"
    detail = "Booking state was updated."
    state = "current"

    if target == "deposit_received":
        deposit_status = "received"
        event_type = "payment.received"
        label = "Deposit received"
        detail = "Deposit has been marked received in LiveUIN TrustPay."
        state = "complete"
    elif target == "confirmed":
        if existing.get("status") == "confirmed":
            return _envelope(status="booking_already_confirmed", workspace_id=workspace_id, booking=existing)
        version_guard = g32_offer_version_gate_for_booking_record(existing, workspace_id)
        if version_guard.get("ok") is False:
            return version_guard
        if existing.get("deposit_status") not in {"received", "not_required"} and deposit_status not in {"received", "not_required"}:
            return error("deposit_not_received", 409, deposit_status=existing.get("deposit_status", ""))
        hold_guard = _require_hold(existing.get("hold_id", ""), workspace_id, existing.get("case_id", ""), existing.get("room_id", ""))
        if hold_guard.get("ok") is False:
            return hold_guard
        inventory_response = inventory_svc.transition_hold(existing.get("hold_id", ""), "booked", request_meta)
        if inventory_response.get("ok") is False:
            return inventory_response
        deposit_status = "received" if int(existing.get("deposit_amount") or 0) > 0 else "not_required"
        event_type = "booking.confirmed"
        label = "Booking confirmed"
        detail = "Booking is confirmed and the room hold is booked in LiveUIN Inventory."
        state = "complete"
        status_group = "booking_confirmed"
    elif target == "cancelled":
        hold = _hold_record(existing.get("hold_id", ""), workspace_id)
        if hold and hold.get("status") in {"active", "booked"}:
            inventory_response = inventory_svc.transition_hold(existing.get("hold_id", ""), "released", request_meta)
            if inventory_response.get("ok") is False:
                return inventory_response
        event_type = "booking.cancelled"
        label = "Booking cancelled"
        detail = "Booking was cancelled and any active hold was released."
        state = "attention"
    elif target in {"expired", "failed"}:
        event_type = "booking." + target
        label = "Booking " + target.replace("_", " ")
        detail = "Booking was marked " + target + "."
        state = "attention"

    updated = store.upsert_booking(
        {
            **existing,
            "status": target,
            "deposit_status": deposit_status,
            "provider_ref": _clean_string(payload.get("provider_ref") or existing.get("provider_ref"), 160),
            "ledger": {
                **_as_dict(existing.get("ledger")),
                **_as_dict(payload.get("ledger")),
                "deposit_state": deposit_status,
                "booking_state": target,
                "canonical_owner": "LiveUIN TrustPay/LiveLedger",
            },
            "booking": {
                **_as_dict(existing.get("booking")),
                "status": target,
                "deposit_status": deposit_status,
            },
            "metadata": {
                **_as_dict(existing.get("metadata")),
                **_as_dict(payload.get("metadata")),
                "last_transition_at": _now_iso(),
            },
            "updated_at": _now(),
        }
    )
    event_id = _append_event(
        event_type=event_type,
        workspace_id=workspace_id,
        case_id=updated.get("case_id", ""),
        booking_id=booking_id,
        hold_id=updated.get("hold_id", ""),
        viewing_id=updated.get("viewing_id", ""),
        room_id=updated.get("room_id", ""),
        payload={"status": target, "deposit_status": deposit_status},
        request_meta=request_meta,
    )
    if event_type in {"payment.received", "booking.confirmed"}:
        _append_case_timeline(
            case_id=updated.get("case_id", ""),
            workspace_id=workspace_id,
            event_type=event_type,
            label=label,
            detail=detail,
            state=state,
            status_group=status_group,
            request_meta=request_meta,
        )
    return _envelope(
        status="booking_" + target,
        workspace_id=workspace_id,
        event_id=event_id,
        booking=updated,
        inventory=inventory_response,
    )


def pass_bookings_for_case(case_id: str, workspace_id: str = DEFAULT_WORKSPACE_ID) -> List[Dict[str, Any]]:
    case_id = _clean_id(case_id, 96)
    workspace_id = _clean_id(workspace_id, 96) or DEFAULT_WORKSPACE_ID
    return [_booking_safe(item) for item in store.list_bookings_for_case(case_id, workspace_id)]


def pass_bookings_for_case_authorized(
    case_id: str,
    workspace_id: str = DEFAULT_WORKSPACE_ID,
    *,
    participant_grant_id: str = "",
    participant_id: str = "",
    identity_resolved: bool = False,
    request_meta: Dict[str, str] | None = None,
) -> Dict[str, Any]:
    case_id = _clean_id(case_id, 96)
    workspace_id = _clean_id(workspace_id, 96) or DEFAULT_WORKSPACE_ID
    guard = g11_svc.enforce_consumer_access(
        consumer="booking_projection",
        workspace_id=workspace_id,
        case_id=case_id,
        grant_id=_clean_id(participant_grant_id, 140),
        participant_id=_clean_id(participant_id, 120),
        identity_resolved=identity_resolved,
        resource_id=case_id,
        request_meta=request_meta,
    )
    if guard.get("ok") is False:
        return guard
    return {**guard, "status": "booking_projection_loaded", "bookings": pass_bookings_for_case(case_id, workspace_id)}


def pass_booking_payments_for_case(case_id: str, workspace_id: str = DEFAULT_WORKSPACE_ID) -> List[Dict[str, Any]]:
    case_id = _clean_id(case_id, 96)
    workspace_id = _clean_id(workspace_id, 96) or DEFAULT_WORKSPACE_ID
    payments = []
    for item in store.list_bookings_for_case(case_id, workspace_id):
        if int(item.get("deposit_amount") or 0) > 0:
            payments.append(_booking_payment_safe(item))
    return payments


